insert into public.exercise_templates (slug, title, description, kind, approach, audience, collection, estimated_minutes, sort_order, steps) values
  ('cuadro-panico-entender', 'Entender los ataques de pánico', 'Qué es un ataque de pánico, por qué se repite, cómo se trabaja en terapia y qué podés hacer entre sesiones.', 'custom', 'tcc', 'todos', 'cuadros', 15, 300,
   $steps$[ { "id": "intro", "type": "info", "title": "Entender el pánico", "content": "Si estás leyendo esto, quizás alguna vez sentiste de golpe que el corazón se aceleraba, que te faltaba el aire o que algo grave estaba por pasar.\n\nEsa experiencia asusta mucho. **No estás exagerando ni te lo estás inventando:** lo que sentís es real.\n\nEn las próximas pantallas vas a ver qué pasa en el cuerpo y en la mente durante una crisis, por qué a veces se repite y qué se puede hacer. Andá a tu ritmo." }, { "id": "que_es", "type": "info", "title": "Qué es un ataque de pánico", "content": "Un ataque de pánico es una **subida intensa y repentina de miedo** que llega a su punto más alto en pocos minutos y después baja sola.\n\nPuede venir con:\n\n- Corazón acelerado o palpitaciones.\n- Falta de aire o sensación de ahogo.\n- Mareo, temblor, sudor, hormigueo.\n- Presión en el pecho o náuseas.\n- Sensación de irrealidad o de estar \"afuera\" de vos.\n- Miedo a desmayarte, a volverte loco/a o a morir.\n\nEs la **alarma natural del cuerpo** (la respuesta de lucha o huida) que se dispara cuando no hay un peligro real delante." }, { "id": "que_no_es", "type": "info", "title": "Qué no es", "content": "- **No es debilidad** ni falta de voluntad. Le pasa a muchísimas personas.\n- **No es \"estar loco/a\".** La sensación de perder el control es parte de la alarma, no una señal de que vayas a perderlo.\n- **No es peligroso en sí mismo,** aunque se sienta terrible. La alarma está hecha para subir y después bajar.\n\nIgual, es importante que un médico o una médica descarte causas físicas, sobre todo la primera vez o si los síntomas cambian. Eso no es \"perder el tiempo\": te da tranquilidad para trabajar el pánico con más confianza." }, { "id": "circulo", "type": "info", "title": "El círculo del pánico", "content": "Muchas veces el pánico se arma como un círculo:\n\n- **Una sensación:** notás el corazón más rápido (por subir una escalera, un café, estrés…).\n- **Una interpretación catastrófica:** \"me está dando un infarto\", \"me voy a desmayar\".\n- **Más miedo:** el cuerpo se alarma todavía más.\n- **Más sensaciones:** el corazón se acelera más, falta el aire.\n\nY vuelta a empezar. No es la sensación la que dispara la crisis, sino **lo que la mente concluye sobre ella**. La buena noticia: ese punto del círculo se puede trabajar." }, { "id": "evitacion", "type": "info", "title": "Por qué se mantiene", "content": "Después de una crisis, es muy entendible querer evitar que vuelva a pasar. Entonces aparecen:\n\n- **Evitación:** dejar de ir a ciertos lugares, de hacer ejercicio, de viajar solo/a.\n- **Conductas de seguridad:** llevar siempre agua o una pastilla \"por las dudas\", ir siempre acompañado/a, sentarte cerca de la salida, controlarte el pulso.\n- **Estar pendiente del cuerpo:** revisar cada latido.\n\nA corto plazo alivian. A largo plazo, le enseñan a la mente que \"me salvé porque evité\", y el miedo no tiene oportunidad de bajar. Así el mundo se va achicando." }, { "id": "tus_sensaciones", "type": "checklist", "prompt": "¿Cuáles de estas sensaciones reconocés en tus crisis? Marcá las que quieras.", "options": [ "Corazón acelerado o palpitaciones", "Falta de aire", "Mareo o sensación de desmayo", "Temblor o sudor", "Presión en el pecho", "Hormigueo", "Sensación de irrealidad", "Náuseas o malestar de panza" ], "min": 1 }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "La terapia cognitivo-conductual es uno de los tratamientos con más respaldo para el pánico. En general incluye:\n\n- **Psicoeducación:** entender la alarma, como estás haciendo ahora.\n- **Revisar las interpretaciones:** buscar explicaciones más realistas para las sensaciones.\n- **Exposición interoceptiva:** con tu psicólogo/a, provocar sensaciones parecidas (por ejemplo, girar en una silla o respirar por una pajita) para que el cuerpo aprenda que no son peligrosas.\n- **Exposición gradual a situaciones evitadas,** de a poco y con un plan.\n- **Dejar de a poco las conductas de seguridad.**\n\nEstos pasos se planifican juntos, a tu ritmo. No hace falta que los hagas solo/a." }, { "id": "mito_respirar", "type": "choice", "prompt": "Mito o realidad: «En una crisis tengo que respirar hondo y rápido para que no me falte el aire».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Exacto, es un mito.** Respirar rápido y hondo suele aumentar el mareo y el hormigueo. Lo que más ayuda es respirar **lento**, alargando la exhalación. La sensación de falta de aire es incómoda, pero el cuerpo sigue recibiendo oxígeno.", "Realidad": "**Es una idea muy común, pero es un mito.** Respirar rápido y hondo suele aumentar el mareo y el hormigueo. Lo que más ayuda es respirar **lento**, alargando la exhalación. La sensación de falta de aire es incómoda, pero el cuerpo sigue recibiendo oxígeno." } }, { "id": "mito_evitar", "type": "choice", "prompt": "Mito o realidad: «Si evito los lugares donde me dio pánico, me voy a sentir mejor con el tiempo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Bien visto.** Evitar trae alivio rápido, pero con el tiempo suele hacer que el miedo crezca y que haya cada vez más lugares \"prohibidos\". Volver de a poco, con un plan acordado en terapia, es lo que ayuda a recuperar terreno.", "Realidad": "**Se entiende que lo pienses, pero es un mito.** Evitar trae alivio rápido, pero con el tiempo suele hacer que el miedo crezca y que haya cada vez más lugares \"prohibidos\". Volver de a poco, con un plan acordado en terapia, es lo que ayuda a recuperar terreno." } }, { "id": "mito_control", "type": "choice", "prompt": "Mito o realidad: «Si no corto la crisis a tiempo, voy a perder el control para siempre».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Así es.** La crisis sube, llega a un pico y baja, aunque no hagas nada especial. La sensación de perder el control es parte de la alarma. Cuanto menos peleás con las sensaciones, más rápido suelen pasar.", "Realidad": "**Es lo que el miedo te dice, pero es un mito.** La crisis sube, llega a un pico y baja, aunque no hagas nada especial. La sensación de perder el control es parte de la alarma. Cuanto menos peleás con las sensaciones, más rápido suelen pasar." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Registrar las crisis:** cuándo, qué sentiste, qué pensaste y qué hiciste. Ayuda a ver el círculo. En esta misma colección tenés la práctica «Mi registro del pánico».\n- **Practicar la respiración lenta** en momentos tranquilos, no solo en la crisis.\n- **Recordarte la frase clave:** \"es la alarma, es incómoda, va a bajar\".\n- **Notar tus conductas de seguridad,** sin presionarte a dejarlas todas de golpe.\n- **Cuidar lo básico:** sueño, comidas, moverte, bajar la cafeína si notás que te afecta.\n\nLlevá lo que observes a la próxima sesión." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si tenés dolor de pecho fuerte, síntomas nuevos o distintos, o no estás seguro/a de que sea pánico, **consultá ya en la guardia del hospital más cercano** o llamá a emergencias.\n\nSi estás en crisis o pensás en hacerte daño, pedí ayuda ya: a emergencias, a una línea de ayuda o en la guardia.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de todo esto? ¿Hay algo que quieras charlar en la próxima sesión?", "placeholder": "Lo que me quedó resonando…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "Las sensaciones que reconozco: {{tus_sensaciones}}. Lo que me llevo: {{me_llevo}}", "content": "Entender el círculo ya es un paso. Lo que anotaste queda guardado y lo podés compartir con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-panico-practica', 'Mi registro del pánico', 'Registrá una crisis, mirá tus sensaciones con otros ojos y practicá una respiración lenta.', 'custom', 'tcc', 'todos', 'cuadros', 12, 301,
   $steps$[ { "id": "intro", "type": "info", "title": "Mi registro del pánico", "content": "Este ejercicio es para hacer **cuando ya estés más tranquilo/a**, no en medio de una crisis.\n\nVas a repasar una crisis reciente (o la última que recuerdes), para ver el círculo del pánico en tu propia experiencia. Después vas a buscar otra forma de leer esas sensaciones y a practicar una respiración lenta.\n\nNo hay respuestas correctas. Escribí lo que te salga." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si ahora mismo estás en una crisis muy fuerte, tenés síntomas nuevos o dolor de pecho intenso, o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "situacion", "type": "text", "prompt": "¿Dónde estabas y qué estabas haciendo cuando empezó la crisis?", "placeholder": "Por ejemplo: en el colectivo, volviendo del trabajo" }, { "id": "sensaciones", "type": "checklist", "prompt": "¿Qué sentiste en el cuerpo? Marcá todas las que aparecieron.", "options": [ "Corazón acelerado", "Falta de aire", "Mareo", "Temblor o sudor", "Presión en el pecho", "Hormigueo", "Sensación de irrealidad", "Náuseas", "Calor o frío de golpe" ], "min": 1 }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué pensaste que estaba pasando o que iba a pasar?", "placeholder": "Por ejemplo: «me va a dar un infarto», «me voy a desmayar»" }, { "id": "creencia", "type": "scale", "prompt": "En ese momento, ¿cuánto creías ese pensamiento?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "que_hiciste", "type": "text", "prompt": "¿Qué hiciste para sentirte a salvo? (irte, llamar a alguien, tomar agua, controlarte el pulso…)", "placeholder": "Lo que hice" }, { "id": "que_paso", "type": "text", "prompt": "¿Qué pasó al final? ¿Se cumplió lo que temías?", "placeholder": "Por ejemplo: a los veinte minutos se me pasó" }, { "id": "reinterpretar_info", "type": "info", "title": "Mirarlo con otros ojos", "content": "Ahora, con más calma, preguntate:\n\n- **¿Qué otra explicación puede tener** lo que sentí? (estrés, cansancio, calor, la alarma del cuerpo)\n- **¿Cuántas veces sentí esto** y qué pasó realmente después?\n- **¿Qué le diría a alguien querido** que me cuenta esto mismo?\n\nNo se trata de convencerte de que \"no es nada\", sino de buscar una explicación **más realista y equilibrada**." }, { "id": "otra_explicacion", "type": "text", "prompt": "Escribí una explicación más realista para lo que sentiste.", "placeholder": "Por ejemplo: «el corazón se aceleró por la alarma del cuerpo; es incómodo, pero baja solo»" }, { "id": "creencia_despues", "type": "scale", "prompt": "Ahora, ¿cuánto creés el pensamiento del principio?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "respiracion", "type": "timed_info", "title": "Respiración lenta", "content": "Sentate cómodo/a. Apoyá una mano en la panza.\n\n- **Inhalá por la nariz** contando hasta 4, sin forzar.\n- **Exhalá despacio por la boca** contando hasta 6, como si soplaras una vela sin apagarla.\n\nNo hace falta llenar los pulmones: lo importante es que la exhalación sea más larga. Si te mareás, volvé a respirar normal.\n\nSeguí así hasta que termine el tiempo. Practicarla en momentos tranquilos hace que después te salga más fácil.", "seconds": 90 }, { "id": "frase", "type": "text", "prompt": "Escribí una frase corta para recordarte la próxima vez que aparezcan las sensaciones.", "placeholder": "Por ejemplo: «Es la alarma. Es incómoda. Va a bajar.»" }, { "id": "resumen", "type": "reflect", "title": "Tu registro", "template": "Situación: {{situacion}}. Lo que sentí: {{sensaciones}}. Lo que pensé: {{pensamiento}}. Otra explicación: {{otra_explicacion}}. Mi frase: {{frase}}", "content": "Llevá este registro a la próxima sesión: ayuda a ver tu propio círculo del pánico y a planificar los próximos pasos con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-fobias-entender', 'Entender las fobias y la ansiedad social', 'Por qué el miedo intenso a algo concreto o a la mirada de los demás se mantiene, y cómo se trabaja en terapia.', 'custom', 'tcc', 'todos', 'cuadros', 15, 302,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando el miedo achica la vida", "content": "Todos tenemos miedos. A veces, sin embargo, el miedo a algo concreto (un animal, la altura, las agujas, volar) o a la mirada de los demás se vuelve tan intenso que empieza a decidir por vos: qué hacés, a dónde vas, con quién hablás.\n\nEn este recurso vas a ver qué son las fobias y la ansiedad social, por qué se mantienen y cómo se trabajan. **Sentir esto no habla mal de vos:** es una forma en que el cerebro intenta protegerte, aunque a veces se pase de rosca." }, { "id": "que_es", "type": "info", "title": "Qué son", "content": "- **Fobia específica:** un miedo intenso a algo puntual (un animal, la sangre, las alturas, los lugares cerrados, volar) que se siente desproporcionado y lleva a evitarlo.\n- **Ansiedad social:** un miedo intenso a ser observado/a, juzgado/a o a pasar vergüenza. Puede aparecer al hablar en público, comer delante de otros, llamar por teléfono, hablar con alguien nuevo o participar en clase o en el trabajo.\n\nEn los dos casos el cuerpo reacciona con alarma (corazón rápido, temblor, sonrojarse, sudor, mente en blanco) y aparece un fuerte impulso de escapar o evitar." }, { "id": "que_no_es", "type": "info", "title": "Qué no es", "content": "- **No es timidez \"de carácter\"** que haya que aceptar sin más. La timidez es común; cuando el miedo te impide hacer lo que te importa, vale la pena trabajarlo.\n- **No es falta de ganas** ni capricho. Muchas personas con ansiedad social desean mucho vincularse.\n- **No es algo que se \"supera\" a la fuerza** tirándose de cabeza a lo más difícil. Se trabaja de a poco y con un plan.\n\nCada persona es distinta: lo que te pasa a vos se entiende mejor charlándolo con tu psicólogo/a." }, { "id": "circulo", "type": "info", "title": "Cómo se mantiene el miedo", "content": "El miedo suele sostenerse con dos estrategias que, a corto plazo, alivian:\n\n- **Evitación:** no ir, no hablar, cancelar, cruzar de vereda.\n- **Conductas de seguridad:** cosas que hacés para \"sobrevivir\" la situación, como no mirar a los ojos, ensayar cada frase, quedarte con el celular, tomar algo antes, hablar poco o taparte la cara.\n\nEl problema es que no te dejan comprobar que podías manejarlo. La mente concluye \"me salvé gracias a eso\", y la próxima vez el miedo es igual o más grande.\n\nEn la ansiedad social, además, la atención se va **hacia adentro** (\"se me nota\", \"estoy rojo/a\"), y eso aumenta la sensación de que todos te miran." }, { "id": "tus_seguridades", "type": "checklist", "prompt": "¿Reconocés alguna de estas conductas de seguridad o de evitación? Marcá las que quieras.", "options": [ "Evitar ir a ciertos lugares o eventos", "Cancelar a último momento", "No mirar a los ojos", "Ensayar mentalmente lo que voy a decir", "Refugiarme en el celular", "Ir solo/a si voy acompañado/a", "Hablar lo mínimo", "Irme apenas puedo" ], "min": 1 }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "La terapia cognitivo-conductual tiene mucho respaldo para fobias y ansiedad social. Suele incluir:\n\n- **Exposición gradual:** armar con tu psicólogo/a una \"escalera\" de situaciones, de la más fácil a la más difícil, y ir subiendo de a un escalón, **a tu ritmo y con acuerdo**.\n- **Soltar de a poco las conductas de seguridad,** para comprobar lo que pasa sin ellas.\n- **Revisar las predicciones:** \"¿qué temo que pase?\" y \"¿qué pasó realmente?\".\n- **Llevar la atención hacia afuera,** a la conversación o la tarea, en lugar de a cómo te ves.\n\nLa idea no es que dejes de sentir ansiedad, sino que **deje de decidir por vos**." }, { "id": "mito_pasar", "type": "choice", "prompt": "Mito o realidad: «Si espero a dejar de tener miedo, después voy a poder enfrentarlo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Exacto.** Esperar a no tener miedo suele hacer que la espera sea eterna. El miedo baja **haciendo**, de a poco, no antes de hacer. Por eso se avanza con pasos chicos y planificados.", "Realidad": "**Es muy entendible pensarlo, pero suele ser un mito.** Esperar a no tener miedo suele hacer que la espera sea eterna. El miedo baja **haciendo**, de a poco, no antes de hacer. Por eso se avanza con pasos chicos y planificados." } }, { "id": "mito_notan", "type": "choice", "prompt": "Mito o realidad: «Todos se dan cuenta de lo nervioso/a que estoy».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Bien.** En general, los demás notan mucho menos de lo que creemos. Como vos sentís todo desde adentro, parece evidente, pero desde afuera casi no se ve. A esto se le llama \"ilusión de transparencia\".", "Realidad": "**Así se siente, pero suele ser un mito.** En general, los demás notan mucho menos de lo que creemos. Como vos sentís todo desde adentro, parece evidente, pero desde afuera casi no se ve. A esto se le llama \"ilusión de transparencia\"." } }, { "id": "mito_golpe", "type": "choice", "prompt": "Mito o realidad: «Para superar una fobia hay que enfrentar lo peor de una, de golpe».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Así es.** La exposición que más se usa es **gradual**: se empieza por algo difícil pero posible y se sube de a poco. Se planifica con tu psicólogo/a para que sea un desafío posible, no algo abrumador.", "Realidad": "**Es un mito bastante extendido.** La exposición que más se usa es **gradual**: se empieza por algo difícil pero posible y se sube de a poco. Se planifica con tu psicólogo/a para que sea un desafío posible, no algo abrumador." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Observar sin juzgarte:** ¿en qué situaciones aparece el miedo? ¿Qué hacés para aliviarlo?\n- **Anotar tus predicciones** (\"qué temo que pase\") para revisarlas en sesión.\n- **Armar tu escalera** con la práctica «Mi escalera de exposición» de esta colección, para después afinarla con tu psicólogo/a.\n- **Practicar llevar la atención afuera:** en una charla, fijate en lo que dice la otra persona, más que en cómo te ves.\n- **Reconocer tus pasos,** aunque sean chicos.\n\nNo hace falta que empieces a exponerte solo/a: eso se acuerda en sesión." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si en algún momento te sentís desbordado/a, en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esto? ¿Qué situación te gustaría poder afrontar más adelante?", "placeholder": "Lo que me llevo y lo que me gustaría lograr…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "Conductas que reconozco: {{tus_seguridades}}. Lo que me llevo: {{me_llevo}}", "content": "Reconocer cómo se mantiene el miedo es el primer escalón. Podés compartir esto con tu psicólogo/a para planificar juntos." } ]$steps$::jsonb),
  ('cuadro-fobias-practica', 'Mi escalera de exposición', 'Armá una escalera de situaciones de menor a mayor malestar para revisarla con tu psicólogo/a.', 'custom', 'tcc', 'todos', 'cuadros', 12, 303,
   $steps$[ { "id": "intro", "type": "info", "title": "Mi escalera de exposición", "content": "Vas a armar una **escalera**: una lista de situaciones relacionadas con tu miedo, ordenadas de la que menos malestar te da a la que más.\n\n**Importante:** hoy solo la armás. **No hace falta que hagas ninguna de estas situaciones todavía.** La escalera se revisa y se ajusta con tu psicólogo/a, y juntos deciden por dónde empezar y cómo.\n\nEs un mapa, no una obligación." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si pensar en estas situaciones te desborda, podés parar cuando quieras y retomarlo otro día.\n\nSi estás en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "miedo", "type": "text", "prompt": "¿A qué le tenés miedo? Describilo con tus palabras.", "placeholder": "Por ejemplo: hablar en reuniones, los perros, los ascensores" }, { "id": "temor", "type": "text", "prompt": "¿Qué temés que pase si te enfrentás a eso?", "placeholder": "Por ejemplo: «se van a reír de mí», «me va a morder», «me voy a quedar encerrado/a»" }, { "id": "costo", "type": "text", "prompt": "¿Qué te está costando este miedo? ¿Qué te gustaría poder hacer?", "placeholder": "Por ejemplo: participar en clase, visitar a mi hermana que tiene perro" }, { "id": "puntaje_info", "type": "info", "title": "El termómetro del malestar", "content": "Para ordenar la escalera vas a usar un puntaje de **0 a 100**:\n\n- **0:** nada de malestar, tranquilidad total.\n- **30:** algo incómodo, pero manejable.\n- **50:** bastante ansiedad, cuesta.\n- **80:** muchísimo malestar.\n- **100:** lo peor que te imaginás.\n\nNo hay puntajes correctos: es tu termómetro. Lo importante es que los números te ayuden a ordenar." }, { "id": "lluvia", "type": "list", "prompt": "Anotá situaciones relacionadas con tu miedo, con su puntaje de 0 a 100. Una por renglón, sin ordenarlas todavía.", "help": "Pensá variantes: más cerca o más lejos, con o sin compañía, más corto o más largo. Por ejemplo: «Mirar fotos de perros: 20», «Saludar a un compañero nuevo: 40».", "count": 10, "min": 5 }, { "id": "ordenar_info", "type": "info", "title": "Ahora, a ordenar", "content": "Mirá la lista que hiciste y elegí entre **5 y 8 situaciones** que vayan subiendo de a poco.\n\n- El **primer escalón** debería ser difícil pero posible (alrededor de 20 a 40).\n- Entre un escalón y otro, que no haya saltos muy grandes.\n- Si falta un escalón intermedio, inventalo: por ejemplo, la misma situación pero acompañado/a, o por menos tiempo." }, { "id": "escalera", "type": "list", "prompt": "Tu escalera: escribí las situaciones de menor a mayor malestar, con su puntaje.", "help": "El primer renglón es el escalón más bajo. Por ejemplo: «1. Ver un video de perros: 25».", "count": 8, "min": 5 }, { "id": "seguridades", "type": "text", "prompt": "¿Qué hacés para sentirte más a salvo en esas situaciones? (conductas de seguridad)", "placeholder": "Por ejemplo: no mirar a los ojos, ir acompañado/a, tener el celular en la mano", "optional": true }, { "id": "confianza", "type": "scale", "prompt": "¿Cuánta confianza tenés en que, con un plan, podrías empezar por el primer escalón?", "min": 0, "max": 10, "min_label": "Ninguna", "max_label": "Mucha" }, { "id": "resumen", "type": "reflect", "title": "Tu escalera", "template": "Mi miedo: {{miedo}}. Lo que temo: {{temor}}. Lo que me gustaría poder hacer: {{costo}}. Mi escalera: {{escalera}}.", "content": "**Llevá esta escalera a la próxima sesión.** Con tu psicólogo/a van a revisar los puntajes, ajustar los escalones y acordar cuándo y cómo empezar. Hasta entonces, no hace falta que la pongas en práctica." } ]$steps$::jsonb),
  ('cuadro-toc-entender', 'Entender el TOC', 'Qué son las obsesiones y las compulsiones, por qué el círculo se mantiene y cómo se trabaja en terapia.', 'custom', 'tcc', 'todos', 'cuadros', 16, 304,
   $steps$[ { "id": "intro", "type": "info", "title": "Entender el TOC", "content": "El trastorno obsesivo-compulsivo (TOC) es mucho más que \"ser ordenado/a\" o \"maniático/a\". Quienes lo viven saben lo agotador que puede ser: pensamientos que no se van y la necesidad de hacer algo para calmarlos.\n\nEn este recurso vas a ver cómo funciona el círculo del TOC, qué no es y cómo se trabaja. **Lo que te pasa tiene explicación y se puede tratar.** Andá a tu ritmo." }, { "id": "obsesiones", "type": "info", "title": "Las obsesiones", "content": "Las **obsesiones** son pensamientos, imágenes o impulsos que aparecen sin que los busques, se sienten intrusivos y generan mucha ansiedad, asco, culpa o sensación de que algo \"no está bien\".\n\nAlgunos temas frecuentes:\n\n- Contaminación o enfermedades.\n- Dudas: \"¿cerré la puerta?\", \"¿apagué la hornalla?\".\n- Miedo a hacer daño a alguien sin querer.\n- Necesidad de orden, simetría o de que algo se sienta \"justo\".\n- Pensamientos que chocan con tus valores (religiosos, sexuales, agresivos).\n\nQue aparezcan **no dice nada de quién sos**. Justamente molestan tanto porque van en contra de lo que querés." }, { "id": "compulsiones", "type": "info", "title": "Las compulsiones", "content": "Las **compulsiones** son lo que hacés para bajar la ansiedad o \"neutralizar\" la obsesión. Pueden ser visibles o mentales:\n\n- Lavar, limpiar, revisar una y otra vez.\n- Ordenar, contar, repetir hasta que \"se sienta bien\".\n- Rezar, repetir frases o pensar un pensamiento \"bueno\" para anular el \"malo\".\n- Pedir que te aseguren que todo está bien.\n- Repasar mentalmente lo que pasó, buscar en internet.\n- Evitar lo que dispara la obsesión.\n\nNo son caprichos: son intentos de protegerte que terminan atrapándote." }, { "id": "circulo", "type": "info", "title": "El círculo del TOC", "content": "El TOC se mantiene en un círculo:\n\n- **Disparador:** tocar un picaporte, salir de casa, una noticia.\n- **Obsesión:** \"me voy a enfermar\", \"¿y si dejé la puerta abierta?\".\n- **Ansiedad o malestar** muy fuerte.\n- **Compulsión o neutralización:** lavarte, volver a revisar, pedir que te aseguren.\n- **Alivio rápido…** que dura poco.\n\nEse alivio le enseña al cerebro que la obsesión era peligrosa y que el ritual \"te salvó\". Entonces la próxima vez la obsesión vuelve con más fuerza y el ritual se hace más largo. **No es tu culpa:** así aprende el cerebro." }, { "id": "que_no_es", "type": "info", "title": "Qué no es", "content": "- **No es \"ser perfeccionista\"** o que te guste el orden. En el TOC, los rituales generan sufrimiento y ocupan mucho tiempo.\n- **Tener un pensamiento no es lo mismo que desearlo ni que hacerlo.** Casi todas las personas tienen pensamientos intrusivos raros; la diferencia está en cuánto pesan y en lo que hacés con ellos.\n- **No es falta de voluntad.** \"Dejar de hacerlo y listo\" no suele funcionar sin ayuda, porque la ansiedad es muy intensa.\n\nSi te reconocés en esto, charlalo con tu psicólogo/a: no tenés que entenderlo todo solo/a." }, { "id": "tus_compulsiones", "type": "checklist", "prompt": "¿Reconocés alguna de estas conductas en tu día a día? Marcá las que quieras.", "options": [ "Lavar o limpiar de más", "Revisar varias veces", "Ordenar o acomodar hasta que esté \"justo\"", "Contar o repetir acciones", "Rezar o repetir frases para anular un pensamiento", "Pedir que me aseguren que todo está bien", "Repasar mentalmente o buscar en internet", "Evitar lugares, objetos o personas" ], "min": 1 }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "El tratamiento psicológico con más respaldo para el TOC es la **exposición con prevención de respuesta (EPR)**, dentro de la terapia cognitivo-conductual.\n\n- **Exposición:** acercarte de a poco, con un plan, a lo que dispara la obsesión.\n- **Prevención de respuesta:** no hacer el ritual (o hacerlo menos), dejando que la ansiedad suba y baje sola.\n\nAsí el cerebro aprende que puede tolerar la duda y el malestar sin el ritual. **La EPR se planifica en sesión, paso a paso y con tu acuerdo.** También pueden sumarse herramientas de ACT, para relacionarte distinto con los pensamientos, y, si hace falta, una evaluación médica o psiquiátrica." }, { "id": "mito_pensar", "type": "choice", "prompt": "Mito o realidad: «Si tengo un pensamiento horrible, es porque en el fondo lo deseo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Exacto.** Los pensamientos intrusivos le pasan a casi todo el mundo. En el TOC molestan tanto **porque van en contra** de lo que valorás. Un pensamiento no es un deseo ni una intención.", "Realidad": "**Es lo que el TOC te hace sentir, pero es un mito.** Los pensamientos intrusivos le pasan a casi todo el mundo. En el TOC molestan tanto **porque van en contra** de lo que valorás. Un pensamiento no es un deseo ni una intención." } }, { "id": "mito_asegurar", "type": "choice", "prompt": "Mito o realidad: «Que me aseguren que todo está bien me ayuda a salir del TOC».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Bien visto.** Pedir que te aseguren funciona como un ritual más: alivia un rato, pero después la duda vuelve y necesitás otra confirmación. En terapia se trabaja, de a poco, también con las personas que te acompañan.", "Realidad": "**Se entiende, porque alivia, pero es un mito.** Pedir que te aseguren funciona como un ritual más: alivia un rato, pero después la duda vuelve y necesitás otra confirmación. En terapia se trabaja, de a poco, también con las personas que te acompañan." } }, { "id": "mito_suprimir", "type": "choice", "prompt": "Mito o realidad: «Lo mejor es esforzarme por no pensar más en eso».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Así es.** Cuanto más intentás no pensar en algo, más vuelve (probá no pensar en un elefante rosa). Lo que ayuda es aprender a dejar que el pensamiento esté, sin engancharte ni responderle con un ritual.", "Realidad": "**Es lo primero que uno intenta, pero es un mito.** Cuanto más intentás no pensar en algo, más vuelve (probá no pensar en un elefante rosa). Lo que ayuda es aprender a dejar que el pensamiento esté, sin engancharte ni responderle con un ritual." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Registrar** obsesiones y compulsiones: qué las disparó, qué sentiste y qué hiciste. En esta colección tenés la práctica «Mi registro del TOC».\n- **Ponerle nombre:** \"esto es el TOC hablando\" ayuda a tomar distancia.\n- **Notar los rituales mentales y los pedidos de que te aseguren,** que a veces pasan desapercibidos.\n- **Tratarte con amabilidad.** Los días con más rituales no son un fracaso.\n- **No armar exposiciones por tu cuenta:** lo ideal es planificarlas en sesión.\n\nLlevá lo que observes a la próxima sesión." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si te sentís desbordado/a, en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esto? ¿Hay algo que quieras charlar en la próxima sesión?", "placeholder": "Lo que me quedó resonando…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "Conductas que reconozco: {{tus_compulsiones}}. Lo que me llevo: {{me_llevo}}", "content": "Entender el círculo del TOC te ayuda a verlo desde un poco más de distancia. Podés compartir esto con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-toc-practica', 'Mi registro del TOC', 'Registrá una obsesión y lo que hiciste con ella, y probá posponer un ritual unos minutos.', 'custom', 'tcc', 'todos', 'cuadros', 12, 305,
   $steps$[ { "id": "intro", "type": "info", "title": "Mi registro del TOC", "content": "Este ejercicio tiene dos partes:\n\n- **Registrar** una obsesión reciente y lo que hiciste con ella, para ver tu propio círculo.\n- **Probar posponer un ritual** unos pocos minutos, solo si te sentís con ganas.\n\n**La exposición con prevención de respuesta (EPR) se planifica en sesión** con tu psicólogo/a. Esto es una práctica chica, de observación, no un reemplazo de ese trabajo." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si en algún momento te desbordás, podés parar y retomarlo otro día.\n\nSi estás en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "disparador", "type": "text", "prompt": "¿Qué pasó justo antes de que apareciera la obsesión? (lugar, situación, algo que viste o tocaste)", "placeholder": "Por ejemplo: salí de casa apurado/a" }, { "id": "obsesion", "type": "text", "prompt": "¿Qué pensamiento, imagen o duda apareció? Podés describirlo en pocas palabras.", "help": "No hace falta que lo escribas con detalle si te incomoda: alcanza con una etiqueta, como «duda sobre la puerta» o «pensamiento de contaminación».", "placeholder": "Por ejemplo: «¿y si dejé la puerta abierta?»" }, { "id": "malestar", "type": "scale", "prompt": "¿Cuánto malestar sentiste en ese momento?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Muchísimo" }, { "id": "ritual", "type": "text", "prompt": "¿Qué hiciste para bajar el malestar? (revisar, lavar, pedir que te aseguren, un ritual mental…)", "placeholder": "Por ejemplo: volví tres veces a revisar" }, { "id": "despues", "type": "text", "prompt": "¿Qué pasó después del ritual? ¿Cuánto duró el alivio?", "placeholder": "Por ejemplo: me calmé un rato, pero a la hora volvió la duda" }, { "id": "posponer_info", "type": "info", "title": "Posponer el ritual", "content": "La próxima vez que aparezca el impulso de hacer un ritual, podés probar **esperar un poco antes de hacerlo**: por ejemplo, 5 minutos.\n\n- No se trata de prohibirte el ritual: solo de **correrlo un rato**.\n- Mientras esperás, notá qué pasa con el malestar: ¿sube, se queda, baja?\n- Si pasados los minutos todavía lo hacés, **está bien.** Es información útil.\n\nElegí algo que te resulte **posible**, no lo más difícil. Si un ritual te genera mucho malestar o te pone en riesgo, dejalo para trabajarlo en sesión." }, { "id": "minutos", "type": "choice", "prompt": "¿Cuánto tiempo te parece posible posponer un ritual esta semana?", "options": [ "2 minutos", "5 minutos", "10 minutos", "Prefiero charlarlo primero en sesión" ], "feedback": { "2 minutos": "**Un buen comienzo.** Dos minutos alcanzan para empezar a notar qué pasa con el malestar cuando no respondés enseguida.", "5 minutos": "**Bien.** Cinco minutos es un desafío razonable. Fijate qué pasa con el malestar mientras esperás.", "10 minutos": "**Bien.** Si en algún momento se vuelve demasiado, podés achicar el tiempo: lo importante es practicar, no aguantar a toda costa.", "Prefiero charlarlo primero en sesión": "**Es una decisión válida.** Con lo que registraste hoy ya tenés mucho para trabajar con tu psicólogo/a." } }, { "id": "pausa", "type": "timed_info", "title": "Un minuto para practicar", "content": "Si ahora sentís el impulso de un ritual, podés usar este minuto para practicar. Si no, simplemente respirá.\n\n- Notá el impulso como una ola: sube, llega a un punto y después baja.\n- Ponele nombre: \"esto es el TOC pidiéndome que revise\".\n- Respirá lento, alargando la exhalación.\n- No hace falta discutir con el pensamiento ni convencerte de nada. Solo dejalo estar.", "seconds": 60 }, { "id": "aprendi", "type": "text", "prompt": "¿Qué notaste hoy sobre tu círculo del TOC?", "placeholder": "Por ejemplo: el alivio dura poco y después necesito revisar más" }, { "id": "resumen", "type": "reflect", "title": "Tu registro", "template": "Disparador: {{disparador}}. Obsesión: {{obsesion}}. Lo que hice: {{ritual}}. Después: {{despues}}. Para esta semana: {{minutos}}. Lo que noté: {{aprendi}}", "content": "Llevá este registro a la próxima sesión. Con tu psicólogo/a van a usarlo para planificar la EPR paso a paso." } ]$steps$::jsonb),
  ('cuadro-trauma-entender', 'Entender el trauma y el estrés postraumático', 'Cómo puede reaccionar la mente y el cuerpo después de una experiencia muy difícil, y cómo se trabaja en terapia.', 'custom', 'tcc', 'todos', 'cuadros', 15, 306,
   $steps$[ { "id": "intro", "type": "info", "title": "Antes de empezar", "content": "Este recurso habla de las reacciones que pueden aparecer después de vivir algo muy difícil. **No te va a pedir que cuentes ni recuerdes lo que te pasó.**\n\nSi en algún momento te sentís muy movilizado/a, podés parar, hacer algo que te calme y volver otro día. Tu bienestar es lo primero.\n\nLo que leas acá es información general: cada historia es única, y tu psicólogo/a te va a ayudar a entender la tuya." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si estás en peligro, si alguien te está lastimando, si estás en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos, y también herramientas para bajar la intensidad cuando lo necesites." }, { "id": "que_es", "type": "info", "title": "Qué es una experiencia traumática", "content": "Una experiencia traumática es algo que vivimos (o presenciamos) en lo que sentimos que nuestra vida, nuestro cuerpo o el de alguien querido estaban en peligro. Por ejemplo: un accidente, una agresión, un abuso, una catástrofe o una pérdida repentina.\n\nDespués de algo así, **es muy común** tener reacciones fuertes durante un tiempo. Para muchas personas, esas reacciones van bajando con las semanas. Para otras, se quedan y siguen afectando el día a día: ahí se puede hablar de **estrés postraumático**, y es algo que se trata." }, { "id": "reacciones", "type": "info", "title": "Cómo puede manifestarse", "content": "Las reacciones suelen agruparse así:\n\n- **Reexperimentación:** recuerdos que aparecen sin buscarlos, pesadillas, sentir como si volviera a pasar, reacciones fuertes ante algo que lo recuerda.\n- **Evitación:** no querer pensar ni hablar de eso, evitar lugares, personas o situaciones.\n- **Cambios en el ánimo y en cómo ves las cosas:** culpa, vergüenza, sentirte desconectado/a, pensar que el mundo es totalmente peligroso.\n- **Hiperalerta:** estar siempre en guardia, sobresaltarte fácil, dormir mal, irritabilidad, dificultad para concentrarte.\n\nNo hace falta tener todas. Y tenerlas **no significa que estés \"roto/a\"**: es la forma en que el cuerpo intenta protegerte." }, { "id": "circulo", "type": "info", "title": "Por qué a veces no se va", "content": "Después de un trauma, el cerebro queda como una alarma muy sensible: detecta peligro donde a veces ya no lo hay.\n\nEntonces aparece un círculo:\n\n- Algo te lo recuerda y **la alarma se dispara** (recuerdos, angustia, el cuerpo en tensión).\n- Para no sentir eso, **evitás** recuerdos, lugares o conversaciones.\n- Evitar alivia, pero **el recuerdo queda \"sin procesar\"** y la alarma sigue sensible.\n- Además, quedarte en **hiperalerta** te mantiene agotado/a y en guardia.\n\nEvitar tiene sentido: fue una forma de sobrevivir. En terapia se busca, con cuidado, que ya no haga falta tanto." }, { "id": "que_no_es", "type": "info", "title": "Lo que no es", "content": "- **No es debilidad.** Cualquier persona puede tener estas reacciones después de algo muy difícil.\n- **No es tu culpa** lo que te pasó, ni cómo reaccionaste en ese momento. Paralizarse, no poder defenderse o no recordar bien son respuestas comunes del cuerpo ante el peligro.\n- **No tenés que \"superarlo\" solo/a ni rápido.** Cada proceso tiene sus tiempos.\n- **No hace falta contarlo todo para que la terapia ayude.** Vos decidís qué, cuándo y cuánto compartir." }, { "id": "reconoces", "type": "checklist", "prompt": "¿Reconocés alguna de estas reacciones en vos últimamente? Marcá las que quieras, sin entrar en detalles.", "options": [ "Recuerdos que aparecen sin buscarlos", "Pesadillas o mal sueño", "Evitar lugares, personas o temas", "Estar siempre en guardia", "Sobresaltarme fácil", "Sentirme desconectado/a", "Culpa o vergüenza", "Irritabilidad", "Prefiero no marcar nada ahora" ], "min": 1 }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "Hay tratamientos con buen respaldo para el estrés postraumático:\n\n- **Primero, seguridad y estabilización:** construir herramientas para calmar el cuerpo, ampliar tu \"ventana de tolerancia\" y cuidar el día a día.\n- **Terapias centradas en el trauma,** como la TCC focalizada en el trauma o la terapia de procesamiento cognitivo, que ayudan a revisar lo vivido y las conclusiones que dejó (culpa, peligro, desconfianza).\n- **EMDR,** otra opción con respaldo, que el profesional puede evaluar si es adecuada para vos.\n\nQué abordaje usar, cuándo y a qué ritmo lo decide tu psicólogo/a junto con vos. **El trabajo con los recuerdos se hace en sesión, acompañado/a, nunca solo/a.**" }, { "id": "mito_olvidar", "type": "choice", "prompt": "Mito o realidad: «Lo mejor es no pensar nunca más en lo que pasó; con el tiempo se va solo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Bien visto.** A veces el tiempo ayuda, pero cuando las reacciones siguen, evitar todo suele mantener la alarma encendida. Eso no significa que tengas que enfrentarlo solo/a: se trabaja en terapia, con cuidado y a tu ritmo.", "Realidad": "**Se entiende que lo pienses: evitar alivia.** Pero cuando las reacciones siguen, evitar todo suele mantener la alarma encendida. Eso no significa que tengas que enfrentarlo solo/a: se trabaja en terapia, con cuidado y a tu ritmo." } }, { "id": "mito_culpa", "type": "choice", "prompt": "Mito o realidad: «Si no reaccioné o no me defendí, en parte fue mi culpa».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Así es.** Quedarse paralizado/a, no poder moverse o hacer lo que el otro pedía son respuestas automáticas del cuerpo para sobrevivir. No son una elección. La responsabilidad es de quien causó el daño.", "Realidad": "**Es una idea muy frecuente y muy dolorosa, pero es un mito.** Quedarse paralizado/a, no poder moverse o hacer lo que el otro pedía son respuestas automáticas del cuerpo para sobrevivir. No son una elección. La responsabilidad es de quien causó el daño." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Practicar herramientas de anclaje** para cuando la alarma se dispare. En esta colección tenés «Anclarme al presente».\n- **Cuidar lo básico:** horarios de sueño, comidas, moverte, contacto con personas seguras.\n- **Tener a mano tu plan** para momentos difíciles (en **Calmarme**).\n- **Notar qué te dispara** la alarma, sin entrar en el recuerdo.\n- **No forzarte** a recordar ni escribir lo que pasó por tu cuenta: eso se hace en sesión, si y cuando corresponda.\n- **Evitar calmarte con alcohol u otras sustancias:** alivian un rato, pero suelen empeorar las cosas." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esto? ¿Qué te gustaría charlar con tu psicólogo/a?", "placeholder": "Lo que me quedó resonando…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "Lo que me llevo: {{me_llevo}}", "content": "Gracias por darte este espacio. Si quedaste movilizado/a, tomate un momento para hacer algo que te calme: respirar lento, tomar algo caliente, salir a caminar o hablar con alguien de confianza." } ]$steps$::jsonb),
  ('cuadro-trauma-practica', 'Anclarme al presente', 'Herramientas de anclaje (5-4-3-2-1), tu ventana de tolerancia y un plan de autocuidado para los días difíciles.', 'custom', 'regulacion', 'todos', 'cuadros', 12, 307,
   $steps$[ { "id": "intro", "type": "info", "title": "Anclarme al presente", "content": "Este ejercicio te ayuda a **volver al aquí y ahora** cuando la mente o el cuerpo se van a momentos difíciles.\n\n**No vas a tener que recordar, contar ni escribir nada de lo que te pasó.** Todo el ejercicio está puesto en el presente: tus sentidos, tu cuerpo y lo que te hace bien.\n\nPodés parar cuando quieras." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si estás en peligro, si alguien te está lastimando, si estás en crisis o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "ahora", "type": "scale", "prompt": "¿Cuánta tensión o malestar sentís en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "ventana", "type": "info", "title": "Tu ventana de tolerancia", "content": "Imaginá una ventana. **Adentro** es donde podés sentir emociones, aunque sean intensas, y seguir pensando y actuando.\n\nA veces el cuerpo sale de la ventana:\n\n- **Por arriba (hiperactivación):** corazón acelerado, angustia, enojo, ganas de escapar, estar en guardia.\n- **Por abajo (hipoactivación):** sentirte apagado/a, entumecido/a, desconectado/a, como \"en piloto automático\".\n\nNo es culpa tuya: es el sistema de alarma. Las herramientas de anclaje ayudan a **volver a la ventana**, y con práctica la ventana se puede ir ampliando." }, { "id": "senales", "type": "checklist", "prompt": "¿Qué señales te avisan que estás saliendo de tu ventana? Marcá las que reconozcas.", "options": [ "Corazón acelerado o respiración rápida", "Tensión en el cuerpo", "Ganas de escapar o de pelear", "Irritabilidad", "Sentirme entumecido/a o apagado/a", "Sentir que las cosas no son reales", "Mente en blanco", "Cansancio de golpe" ], "min": 1 }, { "id": "grounding", "type": "timed_info", "title": "5-4-3-2-1", "content": "Mirá a tu alrededor y, sin apuro, nombrá en voz baja o mentalmente:\n\n- **5 cosas que ves.** Fijate en colores y formas.\n- **4 cosas que podés tocar.** La silla, la ropa, el piso bajo tus pies.\n- **3 sonidos** que escuchás.\n- **2 olores** (o dos olores que te gusten, si no notás ninguno).\n- **1 cosa** que puedas saborear, o algo amable que te digas.\n\nDespués, decite: **\"Estoy acá, hoy, en este lugar. Ahora estoy a salvo.\"**", "seconds": 120 }, { "id": "cuerpo", "type": "timed_info", "title": "Anclar el cuerpo", "content": "Ahora probá anclar el cuerpo:\n\n- **Apoyá bien los pies** en el piso y sentí el peso.\n- **Empujá suavemente** las palmas una contra otra durante unos segundos y soltá.\n- **Respirá lento,** con la exhalación un poco más larga que la inhalación.\n- Si te sirve, **sostené algo** con una textura o temperatura marcada (algo frío, una tela suave).\n\nSi alguna de estas cosas te incomoda, dejala y quedate con la que te haga bien.", "seconds": 90 }, { "id": "despues", "type": "scale", "prompt": "¿Y ahora, cuánta tensión o malestar sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "herramientas", "type": "checklist", "prompt": "¿Qué herramientas te gustaría tener a mano cuando salgas de tu ventana?", "options": [ "El 5-4-3-2-1", "Pies en el piso y respiración lenta", "Agua fría en las manos o la cara", "Un objeto con textura o un aroma que me guste", "Salir a caminar", "Escuchar música tranquila", "Hablar con una persona segura", "Una frase que me recuerde que hoy estoy a salvo" ], "min": 1 }, { "id": "autocuidado", "type": "list", "prompt": "Tu plan de autocuidado: ¿qué cosas chicas te hacen bien en el día a día?", "help": "Por ejemplo: dormir a horario, tomar mate al sol, caminar, ver una serie liviana, cocinar algo rico.", "count": 5, "min": 2 }, { "id": "personas", "type": "list", "prompt": "¿A quién podés recurrir cuando estás pasando un momento difícil?", "help": "Personas seguras: alguien que te escucha sin juzgar y te respeta. No hace falta contarles lo que pasó.", "count": 3, "min": 1 }, { "id": "resumen", "type": "reflect", "title": "Tu plan para anclarte", "template": "Mis señales: {{senales}}. Mis herramientas: {{herramientas}}. Lo que me hace bien: {{autocuidado}}. A quién recurro: {{personas}}.", "content": "Este plan queda guardado y lo podés volver a ver cuando lo necesites. Practicar las herramientas en momentos tranquilos hace que después te salgan más fácil. Si querés, compartilo con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-duelo-entender', 'Entender el duelo', 'Qué es el duelo, por qué no tiene etapas fijas, cómo vamos y venimos entre el dolor y la vida cotidiana, y cuándo pedir más ayuda.', 'custom', 'general', 'todos', 'cuadros', 15, 310,
   $steps$[ { "id": "que_es", "type": "info", "title": "Qué es el duelo", "content": "Si llegaste hasta acá, probablemente perdiste a alguien o algo muy importante. Lo sentimos mucho. Podés recorrer esta guía a tu ritmo y frenar cuando quieras.\n\nEl duelo es la respuesta natural a una pérdida significativa. Suele pensarse en la muerte de un ser querido, pero también puede aparecer con una separación, una mudanza, la pérdida de un trabajo, de la salud o de una mascota.\n\nEl duelo puede sentirse en todo el cuerpo y en toda la vida:\n\n- **Emociones:** tristeza, enojo, culpa, alivio, miedo, anhelo.\n- **Cuerpo:** cansancio, cambios en el sueño o el apetito, opresión en el pecho.\n- **Pensamientos:** recuerdos que aparecen de golpe, dificultad para concentrarte.\n- **Vida diaria:** cosas que antes eran simples ahora cuestan.\n\n**El duelo no es una enfermedad.** Es una forma de amor que sigue buscando a quien ya no está." }, { "id": "sin_etapas", "type": "info", "title": "No hay etapas fijas", "content": "Tal vez escuchaste que el duelo tiene cinco etapas que se recorren en orden. Esa idea se volvió muy popular, pero hoy sabemos que **la mayoría de las personas no vive el duelo así**.\n\nLo más común es que las emociones vayan y vengan, que un día te sientas mejor y al siguiente vuelva el dolor, sobre todo en fechas especiales, aniversarios o lugares cargados de recuerdos.\n\nEso no quiere decir que estés retrocediendo. **No hay una forma correcta ni un calendario** para hacer el duelo. Cada persona y cada vínculo son distintos." }, { "id": "proceso_dual", "type": "info", "title": "Ir y venir: el proceso dual", "content": "Un modelo muy útil para entender el duelo dice que oscilamos entre dos movimientos:\n\n- **Mirar hacia la pérdida:** llorar, recordar, extrañar, mirar fotos, hablar de la persona.\n- **Mirar hacia la vida que sigue:** ocuparte de tareas nuevas, retomar rutinas, descansar del dolor, animarte a cosas distintas.\n\nLas dos cosas son necesarias. Quedarse solo en el dolor agota; escapar siempre del dolor tampoco ayuda a procesarlo.\n\n**Ir y venir entre ambos es parte sana del duelo.** Tomarte un respiro, reírte o distraerte no significa que hayas olvidado ni que quieras menos." }, { "id": "donde_estas", "type": "choice", "prompt": "En estos días, ¿hacia dónde sentís que estás mirando más?", "options": [ "Mucho hacia la pérdida", "Mucho hacia la vida cotidiana", "Voy y vengo entre los dos", "No sabría decirlo" ], "feedback": { "Mucho hacia la pérdida": "Es muy comprensible, sobre todo si la pérdida es reciente. Con el tiempo puede ayudar darte pequeños momentos de descanso del dolor, sin culpa.", "Mucho hacia la vida cotidiana": "A veces ocuparnos nos sostiene. Si notás que evitás todo lo que te recuerda la pérdida, puede ayudar darte de a poco algún espacio para recordar.", "Voy y vengo entre los dos": "Ese ir y venir es justamente lo que describe el modelo. No hace falta forzar nada.", "No sabría decirlo": "Está bien no saberlo. Podés ir observándolo estos días, o pensarlo en sesión." } }, { "id": "que_lo_complica", "type": "info", "title": "Qué puede hacerlo más pesado", "content": "Algunas cosas pueden hacer que el duelo se sienta más difícil o se trabe:\n\n- **Evitar todo** lo que recuerda la pérdida, durante mucho tiempo.\n- **Aislarte** y dejar de lado a las personas que te quieren.\n- **Pérdidas repentinas o traumáticas**, o varias pérdidas juntas.\n- **Culpa** o temas que quedaron sin resolver con la persona.\n- **Poco descanso**, mala alimentación o más alcohol para aguantar.\n- **Sentir que no te dejan hacer el duelo**, porque te apuran o no se habla de la pérdida.\n\nNada de esto es tu culpa. Solo son cosas a tener en cuenta y que se pueden trabajar." }, { "id": "cuando_consultar", "type": "info", "title": "Cuándo pedir más ayuda", "content": "La mayoría de las personas, con el tiempo y con apoyo, encuentra una forma de seguir viviendo con la pérdida. A veces, en cambio, el dolor se queda muy intenso y no cede.\n\nVale la pena consultar con un profesional si, pasado bastante tiempo (en adultos suele hablarse de alrededor de un año):\n\n- El anhelo o la preocupación por la persona ocupan casi todo tu día.\n- Sentís que una parte tuya murió o que la vida no tiene sentido.\n- No podés aceptar la pérdida o evitás todo lo que la recuerda.\n- Te cuesta mucho retomar tu trabajo, tus vínculos o tus actividades.\n\nNo hace falta esperar: **podés pedir ayuda en cualquier momento** del duelo." }, { "id": "seguridad", "type": "info", "title": "Si el dolor se vuelve insoportable", "content": "En el duelo a veces aparecen pensamientos como «no quiero seguir sin esa persona» o «ojalá no despertara». Si te pasa, no estás solo/a y no tenés que cargarlo en silencio.\n\n**Si aparecen pensamientos de no querer vivir, de hacerte daño, o sentís que no podés mantenerte a salvo, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. También podés avisarle a alguien de confianza para que te acompañe.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "en_terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "La terapia no busca que olvides ni que «superes» a la persona. Busca acompañarte para que puedas llevar la pérdida de una forma que te permita seguir viviendo.\n\nAlgunas cosas que se suelen trabajar:\n\n- Darle lugar a la historia de la pérdida y a lo que sentís, sin juicio.\n- Mantener un **vínculo de otra forma** con quien ya no está: recuerdos, rituales, legados.\n- Trabajar la culpa, el enojo o lo que quedó pendiente.\n- Retomar de a poco actividades y personas importantes.\n- Pensar qué es importante para vos ahora y cómo querés vivir.\n\nVamos a tu ritmo. Vos marcás qué se puede hablar y cuándo." }, { "id": "mito_tiempo", "type": "choice", "prompt": "Mito o realidad: «Si después de unos meses sigo llorando, algo anda mal conmigo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** El duelo no tiene fecha de vencimiento. Llorar meses después, sobre todo en fechas especiales, es muy común. Lo que importa es si, de a poco, podés también seguir con tu vida.", "Realidad": "**En realidad, es un mito.** El duelo no tiene fecha de vencimiento. Llorar meses después es muy común. Lo que importa es si, de a poco, podés también seguir con tu vida." } }, { "id": "mito_olvidar", "type": "choice", "prompt": "Mito o realidad: «Para estar bien tengo que dejar de pensar en la persona».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** Muchas personas mantienen un vínculo con quien murió a través de recuerdos y rituales, y eso puede ser fuente de consuelo.", "Realidad": "**En realidad, es un mito.** No hace falta cortar el vínculo. Muchas personas lo mantienen a través de recuerdos y rituales, y eso puede ser fuente de consuelo." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "Pequeñas cosas que suelen ayudar:\n\n- **Cuidar lo básico:** dormir, comer algo nutritivo, moverte un poco.\n- **Darte un momento para recordar**, por ejemplo mirando una foto o escribiendo.\n- **Darte también un descanso del dolor**, sin culpa.\n- **Hablar con alguien de confianza**, aunque sea un rato.\n- **Prepararte para las fechas difíciles** pensando cómo querés pasarlas.\n- **Ser amable con vos:** hay días en los que alcanza con lo mínimo.\n\nEn la práctica «Duelo: recuerdo y conexión» vas a poder trabajar algunas de estas ideas." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esta guía? ¿Qué idea te sirvió o te quedó dando vueltas?", "placeholder": "Lo que me llevo…", "help": "Gracias por darte este tiempo. Si querés, traé esto a la próxima sesión para conversarlo." } ]$steps$::jsonb),
  ('cuadro-duelo-practica', 'Duelo: recuerdo y conexión', 'Una práctica para escribirle a quien perdiste o guardar un recuerdo, pensar un ritual de conexión y apoyarte en tu red.', 'custom', 'general', 'todos', 'cuadros', 15, 311,
   $steps$[ { "id": "intro", "type": "info", "title": "Una práctica para tu duelo", "content": "Este ejercicio te propone tres cosas: **escribir** algo para la persona o lo que perdiste, pensar un **ritual** que te ayude a sentirte en conexión, y mirar quiénes forman tu **red de apoyo**.\n\nPuede movilizar emociones fuertes. Es esperable. Buscá un lugar tranquilo y un momento en el que no tengas que salir corriendo después.\n\nPodés frenar cuando quieras, saltear lo que no te sale hoy y volver otro día." }, { "id": "seguridad", "type": "info", "title": "Si te sentís muy mal", "content": "Si mientras hacés el ejercicio el dolor se vuelve insoportable, frená y hacé algo que te calme: respirar despacio, tomar agua, llamar a alguien.\n\n**Si aparecen pensamientos de no querer vivir o de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "como_llegas", "type": "scale", "prompt": "Antes de empezar, ¿cuánto dolor o malestar sentís ahora?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "forma", "type": "choice", "prompt": "¿Qué preferís hacer hoy?", "options": [ "Escribir una carta", "Escribir un recuerdo significativo" ], "feedback": { "Escribir una carta": "En la próxima pantalla podés escribirle directamente. Algunas ideas: qué te gustaría que supiera, qué extrañás, qué le agradecés, qué te quedó pendiente decir.", "Escribir un recuerdo significativo": "En la próxima pantalla contá un momento compartido: dónde estaban, qué pasaba, qué sentías. Con todos los detalles que quieras." } }, { "id": "escrito", "type": "text", "prompt": "Escribí tu carta o tu recuerdo. No hace falta que esté prolijo ni completo.", "help": "Nadie lo va a leer si vos no querés. Si llorás mientras escribís, está bien: podés hacer una pausa y seguir.", "placeholder": "Querido/a… / Me acuerdo de cuando…" }, { "id": "como_quedaste", "type": "text", "prompt": "¿Cómo te quedaste después de escribir? ¿Qué notaste?", "optional": true, "placeholder": "Lo que sentí…" }, { "id": "rituales", "type": "info", "title": "Rituales de conexión", "content": "Los rituales son gestos que nos ayudan a darle un lugar a la pérdida y a sentir que el vínculo sigue de otra forma. Pueden ser muy simples:\n\n- Encender una vela o poner una flor en una fecha especial.\n- Cocinar su comida favorita o escuchar su música.\n- Visitar un lugar que compartían.\n- Armar una caja o un álbum de recuerdos.\n- Hacer algo que a esa persona le importaba, como un pequeño legado.\n\nElegí lo que tenga sentido para vos y para tus creencias." }, { "id": "ritual", "type": "text", "prompt": "¿Qué ritual o gesto de conexión te gustaría hacer? ¿Cuándo?", "placeholder": "Por ejemplo: el domingo voy a cocinar su receta de…" }, { "id": "red", "type": "list", "prompt": "¿Con quiénes podés hablar de tu pérdida o pedir compañía?", "help": "Pueden ser familiares, amistades, alguien de tu comunidad o tu psicólogo/a. Un nombre por renglón.", "count": 3, "min": 1 }, { "id": "pedido", "type": "text", "prompt": "¿Qué te gustaría pedirle a alguna de esas personas esta semana?", "optional": true, "placeholder": "Por ejemplo: que me acompañe al cementerio, que me llame el viernes…" }, { "id": "como_salis", "type": "scale", "prompt": "Ahora, ¿cuánto dolor o malestar sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Tu plan de conexión", "template": "Mi ritual de conexión: {{ritual}}. Personas con las que puedo hablar: {{red}}.", "content": "Si el malestar subió, es normal después de tocar algo tan importante: date un momento de cuidado. Podés traer lo que escribiste a la próxima sesión, si querés." } ]$steps$::jsonb),
  ('cuadro-burnout-entender', 'Entender el estrés laboral y el burnout', 'Qué es el burnout, en qué se diferencia del estrés común, qué factores del trabajo y personales lo alimentan y cómo se trabaja.', 'custom', 'tcc', 'todos', 'cuadros', 15, 312,
   $steps$[ { "id": "que_es", "type": "info", "title": "Qué es el burnout", "content": "Todos tenemos épocas de mucho trabajo. El **estrés** suele sentirse como «demasiado»: demasiadas tareas, demasiada presión, pero con la idea de que, si se termina, vas a estar mejor.\n\nEl **burnout** o **síndrome de desgaste profesional** es otra cosa: aparece cuando el estrés del trabajo se sostiene mucho tiempo sin que haya suficiente recuperación. Se siente más como «no queda nada»: te vaciaste.\n\nNo es una debilidad ni falta de compromiso. Muchas veces les pasa justamente a personas muy comprometidas con lo que hacen." }, { "id": "tres_senales", "type": "info", "title": "Tres señales principales", "content": "El burnout suele describirse con tres componentes:\n\n- **Agotamiento:** cansancio físico y emocional que no se va con un fin de semana. Te levantás cansado/a.\n- **Distanciamiento o cinismo:** el trabajo te genera rechazo, te volvés más irritable, distante o indiferente con las tareas o las personas.\n- **Menor eficacia:** sentís que rendís menos, que nada de lo que hacés alcanza o que ya no sos bueno/a en lo tuyo.\n\nTambién pueden aparecer dolores de cabeza, problemas de sueño, más enfermedades o más consumo de café, alcohol u otras sustancias para aguantar." }, { "id": "senales_propias", "type": "checklist", "prompt": "¿Cuáles de estas señales reconocés en vos últimamente?", "options": [ "Me levanto cansado/a aunque duerma", "Siento rechazo o irritación con el trabajo", "Me volví más distante con compañeros o clientes", "Siento que nada de lo que hago alcanza", "Me cuesta desconectarme fuera del horario", "Ninguna por ahora" ], "help": "No es un test ni un diagnóstico. Es solo para que puedas mirarte con más claridad.", "min": 1 }, { "id": "factores", "type": "info", "title": "Factores del trabajo y factores personales", "content": "El burnout no depende solo de vos. La investigación muestra que tiene mucho que ver con **cómo está organizado el trabajo**:\n\n- Carga excesiva o plazos imposibles.\n- Poco control sobre cómo y cuándo hacés las cosas.\n- Poco reconocimiento o pago injusto.\n- Mal clima, conflictos o falta de apoyo.\n- Choque entre tus valores y lo que te piden hacer.\n\nTambién influyen **factores personales**: perfeccionismo, dificultad para decir que no, sentir que tu valor depende de rendir, o tener muchas otras cargas (cuidados, estudios, problemas económicos).\n\nMirar las dos partes ayuda a no culparte y a buscar cambios realistas." }, { "id": "como_se_mantiene", "type": "info", "title": "El círculo que lo mantiene", "content": "Cuando estás agotado/a, es común entrar en un círculo:\n\n- Trabajás más horas para «ponerte al día».\n- Recortás sueño, descanso, ejercicio y encuentros con gente.\n- Tenés menos energía y te cuesta más concentrarte.\n- Rendís menos, te exigís más… y el ciclo sigue.\n\nLa salida no suele estar en esforzarte todavía más, sino en **recuperar la recuperación**: descanso real, límites y cambios en las demandas cuando sea posible." }, { "id": "seguridad", "type": "info", "title": "Si sentís que no das más", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "en_terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "En terapia vamos a mirar tu situación completa, no solo el trabajo. Algunas cosas que se suelen trabajar:\n\n- **Mapear demandas y recursos:** qué te quita energía y qué te la devuelve.\n- **Poner límites** concretos y practicar cómo comunicarlos.\n- Revisar **pensamientos exigentes** como «si no lo hago perfecto, fallé».\n- Recuperar **descanso, actividades placenteras y vínculos**.\n- Reconectar con lo que **te importa** del trabajo y de la vida.\n- Pensar decisiones más grandes, si hacen falta, con calma.\n\nA veces también es importante una consulta médica para descartar otras causas del cansancio." }, { "id": "mito_vacaciones", "type": "choice", "prompt": "Mito o realidad: «Con unas buenas vacaciones el burnout se cura».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** Las vacaciones ayudan, pero si al volver las condiciones son las mismas, el agotamiento suele regresar rápido. Hacen falta cambios sostenidos en el día a día.", "Realidad": "**En realidad, es un mito.** Las vacaciones ayudan, pero si al volver las condiciones son las mismas, el agotamiento suele regresar rápido. Hacen falta cambios sostenidos en el día a día." } }, { "id": "mito_debil", "type": "choice", "prompt": "Mito o realidad: «Si me pasa esto es porque soy débil o no sirvo para el trabajo».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** El burnout tiene mucho que ver con las condiciones del trabajo, y le pasa a gente muy capaz y comprometida. No habla de tu valor como persona.", "Realidad": "**En realidad, es un mito.** El burnout tiene mucho que ver con las condiciones del trabajo, y le pasa a gente muy capaz y comprometida. No habla de tu valor como persona." } }, { "id": "mito_pausas", "type": "choice", "prompt": "Mito o realidad: «Las pausas cortas durante la jornada ayudan a recuperar energía».", "options": [ "Mito", "Realidad" ], "feedback": { "Realidad": "**Correcto: es real.** Pausas breves y frecuentes, sobre todo si te movés o te alejás de la pantalla, ayudan a sostener la energía y la concentración a lo largo del día.", "Mito": "**En realidad, es real.** Pausas breves y frecuentes, sobre todo si te movés o te alejás de la pantalla, ayudan a sostener la energía y la concentración a lo largo del día." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "Algunas ideas para empezar, de a poco:\n\n- **Marcar un fin a la jornada:** un horario o un ritual para «cerrar» el trabajo.\n- **Micro-pausas:** unos minutos cada una o dos horas para pararte, estirarte o respirar.\n- **Proteger el sueño** y alguna actividad que te guste, aunque sea corta.\n- **Elegir un límite pequeño** y practicarlo, por ejemplo no contestar mensajes de noche.\n- **Hablar con alguien** de confianza sobre cómo estás.\n\nEn la práctica «Burnout: demandas, recursos y límites» vas a poder armar tu propio plan." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esta guía? ¿Qué idea te sirvió o te quedó dando vueltas?", "placeholder": "Lo que me llevo…", "help": "Si querés, traé esto a la próxima sesión para conversarlo." } ]$steps$::jsonb),
  ('cuadro-burnout-practica', 'Burnout: demandas, recursos y límites', 'Hacé un inventario de lo que te quita y te da energía, elegí límites concretos, sumá micro-pausas y armá un plan de recuperación.', 'custom', 'tcc', 'todos', 'cuadros', 15, 313,
   $steps$[ { "id": "intro", "type": "info", "title": "Tu plan de recuperación", "content": "En este ejercicio vas a hacer un **inventario** de lo que te quita energía y de lo que te la devuelve, elegir **límites concretos**, planificar **micro-pausas** y armar un **plan de recuperación** para esta semana.\n\nNo se trata de cambiar todo de golpe. Buscamos pasos chicos y realistas." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "energia", "type": "scale", "prompt": "Hoy, ¿cuánta energía sentís que tenés?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Mucha" }, { "id": "demandas", "type": "list", "prompt": "Demandas: ¿qué cosas del trabajo (o de tu vida) te quitan más energía?", "help": "Por ejemplo: reuniones sin fin, mensajes fuera de hora, un cliente difícil, tareas que no son tuyas.", "count": 5, "min": 2 }, { "id": "recursos", "type": "list", "prompt": "Recursos: ¿qué cosas te devuelven energía o te sostienen?", "help": "Por ejemplo: un compañero con quien hablar, caminar, dormir bien, una tarea que disfrutás, tu familia.", "count": 5, "min": 2 }, { "id": "cambiable", "type": "text", "prompt": "De tus demandas, ¿cuál podrías reducir, delegar, negociar o hacer distinto?", "help": "Elegí una sola. No tiene que ser la más grande: mejor una en la que tengas algo de control.", "placeholder": "Por ejemplo: pedir que las reuniones de los lunes sean más cortas" }, { "id": "limites", "type": "checklist", "prompt": "¿Qué límites concretos te gustaría probar esta semana?", "options": [ "No mirar mensajes del trabajo después de cierta hora", "Tomarme el tiempo completo del almuerzo", "Decir «déjame ver mi agenda» antes de aceptar algo", "Pedir ayuda o delegar una tarea", "Terminar la jornada a un horario fijo", "Avisar con tiempo cuando un plazo no es realista" ], "min": 1, "max": 3 }, { "id": "frase_limite", "type": "text", "prompt": "Escribí cómo vas a decir uno de esos límites, con tus palabras.", "help": "Una forma simple: lo que necesitás + una alternativa. Por ejemplo: «Hoy no llego con eso; puedo entregarlo el jueves a la mañana».", "placeholder": "Lo que voy a decir…" }, { "id": "pausas_info", "type": "timed_info", "title": "Probá una micro-pausa ahora", "content": "Durante el próximo minuto:\n\n- Alejá la vista de la pantalla y mirá algo lejano.\n- Soltá los hombros y la mandíbula.\n- Respirá despacio, con la exhalación un poco más larga que la inhalación.\n- Si podés, parate y estirate.\n\nEsto es una micro-pausa. Unas cuantas a lo largo del día suman.", "seconds": 60 }, { "id": "pausas_plan", "type": "text", "prompt": "¿Cuándo y cómo vas a hacer tus micro-pausas en la jornada?", "placeholder": "Por ejemplo: cada dos horas, 3 minutos para caminar y tomar agua" }, { "id": "recuperacion", "type": "list", "prompt": "Plan de recuperación: ¿qué vas a hacer fuera del trabajo para recargar?", "help": "Pensá en descanso, movimiento, vínculos y algo que disfrutes. Cosas chicas y posibles.", "count": 3, "min": 1 }, { "id": "resumen", "type": "reflect", "title": "Tu plan para esta semana", "template": "Voy a trabajar sobre: {{cambiable}}. Mis límites: {{limites}}. Lo voy a decir así: «{{frase_limite}}». Micro-pausas: {{pausas_plan}}. Para recargar: {{recuperacion}}.", "content": "Al final de la semana, mirá qué funcionó y qué no. Si algo no salió, no es un fracaso: es información para ajustar el plan en sesión." } ]$steps$::jsonb),
  ('cuadro-sueno-entender', 'Entender el insomnio y el sueño', 'Por qué aparece y se mantiene el insomnio, qué es la hiperactivación, cómo la cama se asocia a estar despierto y cómo ayuda la TCC-I.', 'custom', 'tcc', 'todos', 'cuadros', 15, 314,
   $steps$[ { "id": "que_es", "type": "info", "title": "Qué es el insomnio", "content": "Hablamos de **insomnio** cuando cuesta dormirse, te despertás varias veces o muy temprano y no podés volver a dormir, y eso pasa seguido y te afecta durante el día: cansancio, irritabilidad, dificultad para concentrarte.\n\nUna mala noche de vez en cuando le pasa a cualquiera y no es insomnio. Tampoco hay una cantidad exacta de horas que «tenés que» dormir: las necesidades cambian entre personas y con la edad.\n\nLa buena noticia es que el insomnio **se puede trabajar**, y hay tratamientos con mucha evidencia." }, { "id": "tres_p", "type": "info", "title": "Por qué empieza y por qué sigue: las 3 P", "content": "Un modelo muy usado explica el insomnio con tres tipos de factores:\n\n- **Predisponentes:** lo que te hace más propenso/a, como tender a preocuparte o tener un sueño más liviano.\n- **Precipitantes:** lo que lo dispara, como un estrés fuerte, una pérdida, un problema de salud o un cambio de horarios.\n- **Perpetuantes:** lo que hacés para compensar y que, sin querer, lo mantiene: quedarte más tiempo en la cama, dormir siestas largas, acostarte temprano «por las dudas», preocuparte por no dormir.\n\nMuchas veces el disparador ya pasó, pero los factores perpetuantes siguen. **Ahí es donde más se puede trabajar.**" }, { "id": "hiperactivacion", "type": "info", "title": "Hiperactivación: cuerpo y mente en alerta", "content": "Para dormir, el cuerpo y la mente necesitan bajar un cambio. En el insomnio suele pasar lo contrario: hay **hiperactivación**.\n\n- La mente repasa pendientes, problemas o el miedo a no dormir.\n- El cuerpo está tenso, el corazón acelerado.\n- Mirás el reloj, calculás cuántas horas te quedan… y te activás más.\n\nCuanto más te esforzás por dormir, más difícil se vuelve. **El sueño no se puede forzar**: lo que sí podemos hacer es crear las condiciones para que llegue." }, { "id": "condicionamiento", "type": "info", "title": "Cuando la cama se asocia a estar despierto", "content": "Nuestro cerebro aprende por asociación. Si pasás muchas horas en la cama dando vueltas, preocupándote, mirando el celular o la tele, el cerebro empieza a asociar **cama = estar despierto/a y en alerta**.\n\nPor eso a muchas personas con insomnio les pasa que se mueren de sueño en el sillón, pero apenas se acuestan se despiertan.\n\nParte del tratamiento consiste en **reentrenar esa asociación** para que la cama vuelva a ser una señal de sueño." }, { "id": "reconoces", "type": "checklist", "prompt": "¿Cuáles de estas cosas te pasan o hacés seguido?", "options": [ "Me quedo en la cama dando vueltas mucho rato", "Uso el celular o la tele en la cama", "Miro la hora durante la noche", "Duermo siestas largas", "Me acuesto temprano para «recuperar»", "Me preocupo por no poder dormir", "Ninguna de estas" ], "help": "No es un test. Sirve para identificar qué factores podrían estar manteniendo el problema.", "min": 1 }, { "id": "tcc_i", "type": "info", "title": "El tratamiento de primera línea: la TCC-I", "content": "Las guías clínicas recomiendan como **primera opción** para el insomnio crónico la **terapia cognitivo-conductual para el insomnio (TCC-I)**. Suele ser breve y sus efectos tienden a mantenerse en el tiempo.\n\nIncluye, entre otras cosas:\n\n- **Diario de sueño** para conocer tu patrón real.\n- **Control de estímulos:** usar la cama solo para dormir (y la intimidad) y salir de la cama si no te dormís.\n- **Ajuste del tiempo en cama**, siempre planificado y acompañado por el profesional.\n- Trabajar los **pensamientos y preocupaciones** sobre el sueño.\n- **Relajación** y hábitos que favorecen el descanso.\n\nLa medicación para dormir la evalúa un médico; no la empieces ni la dejes por tu cuenta." }, { "id": "seguridad", "type": "info", "title": "Si estás en crisis", "content": "Dormir mal durante mucho tiempo puede hacer que todo se sienta más difícil.\n\n**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi tenés mucho sueño durante el día, evitá manejar o usar máquinas peligrosas, y contáselo a tu profesional." }, { "id": "mito_ocho", "type": "choice", "prompt": "Mito o realidad: «Todos necesitamos dormir exactamente ocho horas».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** La necesidad de sueño varía entre personas. Lo importante es cómo te sentís y funcionás durante el día, no llegar a un número exacto.", "Realidad": "**En realidad, es un mito.** La necesidad de sueño varía entre personas. Lo importante es cómo te sentís y funcionás durante el día, no llegar a un número exacto." } }, { "id": "mito_cama", "type": "choice", "prompt": "Mito o realidad: «Si no me duermo, lo mejor es quedarme en la cama hasta que llegue el sueño».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** Quedarse dando vueltas refuerza la asociación cama-vigilia. Suele ayudar más levantarte, hacer algo tranquilo con poca luz y volver cuando tengas sueño.", "Realidad": "**En realidad, es un mito.** Quedarse dando vueltas refuerza la asociación cama-vigilia. Suele ayudar más levantarte, hacer algo tranquilo con poca luz y volver cuando tengas sueño." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "Algunos primeros pasos:\n\n- **Levantarte a la misma hora** todos los días, incluso el fin de semana.\n- **Usar la cama solo para dormir.** Nada de pantallas ni trabajo en la cama.\n- **Si no te dormís en unos 20 minutos**, levantate, hacé algo tranquilo con poca luz y volvé cuando tengas sueño.\n- **Bajar el ritmo** una hora antes de acostarte.\n- **Evitar cafeína** por la tarde y alcohol cerca de la hora de dormir.\n- **No mirar la hora** durante la noche.\n\nEn la práctica «Sueño: diario y hábitos» vas a poder empezar tu diario de sueño." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esta guía? ¿Qué idea te sirvió o te quedó dando vueltas?", "placeholder": "Lo que me llevo…", "help": "Si querés, traé esto a la próxima sesión para conversarlo." } ]$steps$::jsonb),
  ('cuadro-sueno-practica', 'Sueño: diario y hábitos', 'Aprendé a llevar un diario de sueño durante una semana, revisá tus hábitos y armá tu plan de control de estímulos.', 'custom', 'tcc', 'todos', 'cuadros', 12, 315,
   $steps$[ { "id": "intro", "type": "info", "title": "Conocer tu sueño para cambiarlo", "content": "En este ejercicio vas a preparar tres cosas:\n\n- Un **diario de sueño** para llevar durante una semana.\n- Una revisión de tus **hábitos de sueño**.\n- Tu plan de **control de estímulos**, para que la cama vuelva a ser señal de dormir.\n\nOjo: hay una técnica llamada **restricción de sueño** que reduce el tiempo en cama. Es muy útil, pero **se hace solo con la guía del profesional**. No la pruebes por tu cuenta." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi tenés mucho sueño durante el día, evitá manejar o usar máquinas peligrosas." }, { "id": "diario", "type": "info", "title": "Qué anotar en tu diario de sueño", "content": "Cada mañana, apenas te levantes, anotá en una libreta o en el celular (no durante la noche):\n\n- A qué hora te acostaste.\n- A qué hora apagaste la luz para dormir.\n- Cuánto tardaste, más o menos, en dormirte.\n- Cuántas veces te despertaste y cuánto tiempo estuviste despierto/a.\n- A qué hora te despertaste por última vez y a qué hora te levantaste.\n- Siestas, cafeína, alcohol o medicación del día anterior.\n- Qué tan descansado/a te sentís, del 0 al 10.\n\nNo hace falta que sea exacto: **alcanza con una estimación**. No mires el reloj de noche para anotar." }, { "id": "donde_anotar", "type": "text", "prompt": "¿Dónde y a qué hora vas a completar tu diario cada mañana?", "placeholder": "Por ejemplo: en una libreta en la mesa de la cocina, con el desayuno" }, { "id": "calidad", "type": "scale", "prompt": "En general, ¿cómo venís durmiendo estas últimas semanas?", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien" }, { "id": "habitos", "type": "checklist", "prompt": "Higiene del sueño: ¿qué hábitos te gustaría cambiar?", "options": [ "Tomar café, mate o tereré tarde", "Usar pantallas antes de dormir", "Cenar muy pesado o muy tarde", "Tomar alcohol cerca de la hora de dormir", "Horarios muy distintos entre semana y fin de semana", "Pieza con mucha luz, ruido o calor", "Hacer ejercicio intenso muy tarde" ], "help": "Elegí los que más se parezcan a tu situación. Mejor pocos y posibles.", "min": 1, "max": 3 }, { "id": "control_estimulos", "type": "info", "title": "Control de estímulos", "content": "Estas pautas ayudan a que tu cerebro vuelva a asociar la cama con el sueño:\n\n- **Acostate solo cuando tengas sueño**, no solo cansancio.\n- **Usá la cama solo para dormir** y para la intimidad: nada de celular, tele, trabajo ni comida.\n- **Si no te dormís en unos 20 minutos** (calculalo a ojo, sin mirar el reloj), levantate. Andá a otro lugar, hacé algo tranquilo con poca luz y volvé a la cama cuando tengas sueño. Repetilo las veces que haga falta.\n- **Levantate a la misma hora** todos los días, aunque hayas dormido mal.\n- **Evitá las siestas**, o que sean cortas y antes de media tarde.\n\nLas primeras noches puede costar más. Es esperable: el cambio se nota con constancia." }, { "id": "actividad_tranquila", "type": "text", "prompt": "Si te levantás porque no te dormís, ¿qué cosa tranquila vas a hacer y dónde?", "help": "Algo aburrido o calmo, con poca luz y sin pantallas: leer algo liviano, doblar ropa, escuchar música suave.", "placeholder": "Por ejemplo: leer una revista en el sillón con una lámpara chica" }, { "id": "hora_levantarse", "type": "text", "prompt": "¿A qué hora te vas a levantar todos los días esta semana?", "placeholder": "Por ejemplo: 6:30, también sábado y domingo" }, { "id": "rutina", "type": "list", "prompt": "Armá una rutina para bajar el ritmo en la hora antes de acostarte.", "help": "Por ejemplo: apagar pantallas, ducha tibia, preparar las cosas de mañana, anotar preocupaciones en un papel.", "count": 3, "min": 1 }, { "id": "resumen", "type": "reflect", "title": "Tu plan de sueño", "template": "Voy a completar mi diario: {{donde_anotar}}. Hábitos a cambiar: {{habitos}}. Me levanto todos los días a las {{hora_levantarse}}. Si no me duermo, me levanto y hago esto: {{actividad_tranquila}}. Rutina para bajar el ritmo: {{rutina}}.", "content": "Traé tu diario de sueño a la próxima sesión: con esa información vamos a ver los próximos pasos juntos, incluido si conviene ajustar el tiempo en cama." } ]$steps$::jsonb),
  ('cuadro-tdah-entender', 'Entender el TDAH en adultos', 'Qué es el TDAH en la adultez, cómo afecta a las funciones ejecutivas, por qué no es falta de voluntad y qué estrategias ayudan.', 'custom', 'tcc', 'todos', 'cuadros', 15, 316,
   $steps$[ { "id": "que_es", "type": "info", "title": "Qué es el TDAH", "content": "El **trastorno por déficit de atención e hiperactividad (TDAH)** es una forma diferente de funcionamiento del cerebro que empieza en la infancia y muchas veces continúa en la adultez.\n\nEn adultos puede verse como:\n\n- Distraerte con facilidad o perder el hilo.\n- Postergar tareas, sobre todo las aburridas.\n- Olvidar citas, objetos o pendientes.\n- Llegar tarde o calcular mal el tiempo.\n- Inquietud interna, impaciencia o actuar sin pensar.\n- Concentrarte muchísimo en lo que te interesa y nada en lo que no.\n\nA todos nos pasan estas cosas a veces. En el TDAH son frecuentes, vienen de siempre y afectan varias áreas de la vida." }, { "id": "funciones_ejecutivas", "type": "info", "title": "Las funciones ejecutivas", "content": "Las **funciones ejecutivas** son como el «director de orquesta» del cerebro. Nos ayudan a:\n\n- **Planificar y organizar** los pasos de una tarea.\n- **Empezar** algo aunque no tengamos ganas.\n- **Sostener la atención** y retomar después de una interrupción.\n- **Recordar** lo que teníamos que hacer (memoria de trabajo).\n- **Manejar el tiempo** y anticipar cuánto lleva algo.\n- **Frenar impulsos** y regular emociones.\n\nEn el TDAH estas funciones cuestan más. No es que no sepas qué hacer: el problema suele estar en **hacer lo que sabés, en el momento justo**." }, { "id": "no_es_voluntad", "type": "info", "title": "No es falta de voluntad", "content": "Muchas personas con TDAH crecieron escuchando «sos vago/a», «si quisieras, podrías» o «no te esforzás». Con el tiempo eso puede convertirse en culpa, vergüenza y baja autoestima.\n\nPero el TDAH **no es falta de voluntad, de inteligencia ni de valores**. Es una diferencia en cómo el cerebro regula la atención, la motivación y el tiempo.\n\nPor eso exigirte más fuerza de voluntad no suele alcanzar. Lo que más ayuda es **cambiar el entorno y usar apoyos externos**, en lugar de depender solo de la memoria y la motivación." }, { "id": "estrategias_externas", "type": "info", "title": "Sacar las cosas de la cabeza", "content": "Una idea central es **externalizar**: poner afuera lo que al cerebro le cuesta sostener adentro.\n\n- **Un solo lugar** para anotar pendientes, en vez de papelitos sueltos.\n- **Agenda o calendario** con alarmas para citas y vencimientos.\n- **Temporizadores** para hacer visible el paso del tiempo.\n- **Dividir tareas** grandes en pasos muy chicos y concretos.\n- **Preparar el entorno:** dejar a la vista lo que necesitás y lejos lo que distrae.\n- **Rutinas y lugares fijos** para llaves, documentos, cargador.\n\nNo es hacer trampa: es usar herramientas que se adapten a cómo funciona tu cabeza." }, { "id": "dificultades", "type": "checklist", "prompt": "¿En qué áreas sentís que más te cuesta hoy?", "options": [ "Empezar tareas", "Terminar lo que empiezo", "Recordar citas y pendientes", "Manejar el tiempo", "Mantener el orden", "Controlar impulsos o emociones", "Concentrarme en reuniones o clases" ], "help": "No es un test ni un diagnóstico. Sirve para elegir por dónde empezar.", "min": 1 }, { "id": "diagnostico", "type": "info", "title": "El diagnóstico y la medicación", "content": "Muchas cosas pueden parecerse al TDAH: la ansiedad, la depresión, el mal dormir, el estrés o algunos problemas médicos. Por eso **el diagnóstico lo hace un profesional** con una evaluación cuidadosa, que incluye tu historia desde la infancia.\n\nEsta guía no sirve para diagnosticarte. Si te identificás con lo que leíste, es un buen tema para conversar en sesión.\n\nEn algunos casos la **medicación** puede ayudar mucho. Si corresponde, la evalúa y la indica un médico psiquiatra o neurólogo. La terapia y las estrategias prácticas son un complemento importante, con o sin medicación." }, { "id": "en_terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "La terapia cognitivo-conductual adaptada al TDAH en adultos suele enfocarse en:\n\n- **Organización y planificación:** armar y sostener un sistema externo.\n- **Manejo del tiempo y la postergación.**\n- **Reducir distracciones** y preparar el entorno.\n- **Pensamientos autocríticos** como «siempre arruino todo».\n- **Regulación emocional** y manejo de la impulsividad.\n- **Fortalezas:** creatividad, energía, capacidad de hiperconcentrarte en lo que te apasiona.\n\nSe trabaja con objetivos concretos y practicando en tu vida real, entre sesiones." }, { "id": "seguridad", "type": "info", "title": "Si estás pasando un momento muy difícil", "content": "Vivir con dificultades que nadie entendió puede generar mucho cansancio y frustración.\n\n**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "mito_ninos", "type": "choice", "prompt": "Mito o realidad: «El TDAH es solo de chicos; de grande se te pasa».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** En muchas personas los síntomas continúan en la adultez, aunque a veces cambian de forma: por ejemplo, la hiperactividad puede volverse inquietud interna.", "Realidad": "**En realidad, es un mito.** En muchas personas los síntomas continúan en la adultez, aunque a veces cambian de forma: por ejemplo, la hiperactividad puede volverse inquietud interna." } }, { "id": "mito_concentrar", "type": "choice", "prompt": "Mito o realidad: «Si puedo concentrarme horas en algo que me gusta, no puedo tener TDAH».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "**Correcto: es un mito.** Es muy común en el TDAH poder hiperconcentrarse en lo que interesa. El problema está en regular la atención cuando la tarea no es estimulante.", "Realidad": "**En realidad, es un mito.** Es muy común en el TDAH poder hiperconcentrarse en lo que interesa. El problema está en regular la atención cuando la tarea no es estimulante." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "Algunas ideas para empezar:\n\n- **Elegí un solo lugar** para anotar pendientes y usalo durante una semana.\n- **Poné alarmas** para lo importante, con un aviso previo.\n- **Probá trabajar en bloques cortos** con un temporizador y pausas.\n- **Antes de empezar**, escribí el primer paso más chico posible.\n- **Tratate con amabilidad:** los olvidos y errores son información, no prueba de que fallaste.\n\nEn la práctica «TDAH: mi sistema externo» vas a poder armar tu propio sistema." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de esta guía? ¿Qué idea te sirvió o te quedó dando vueltas?", "placeholder": "Lo que me llevo…", "help": "Si querés, traé esto a la próxima sesión para conversarlo." } ]$steps$::jsonb),
  ('cuadro-tdah-practica', 'TDAH: mi sistema externo', 'Armá un sistema externo con lista, agenda y temporizador, dividí una tarea en pasos chicos, probá bloques cortos y prepará tu entorno.', 'custom', 'tcc', 'todos', 'cuadros', 15, 317,
   $steps$[ { "id": "intro", "type": "info", "title": "Tu sistema externo", "content": "En este ejercicio vas a armar un **sistema externo**: herramientas que hacen fuera de tu cabeza el trabajo que a tu cerebro le cuesta más.\n\nVas a elegir tus herramientas, **dividir una tarea** que venís postergando, planificar **bloques de trabajo** con temporizador y **preparar tu entorno**.\n\nNo tiene que quedar perfecto. Un sistema simple que usás vale más que uno perfecto que abandonás." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "herramientas", "type": "checklist", "prompt": "¿Qué herramientas vas a usar en tu sistema?", "options": [ "Una lista única de pendientes", "Agenda o calendario con alarmas", "Temporizador", "Notas a la vista (pizarra, post-its)", "Recordatorios del celular", "Una persona que me acompañe o me pregunte cómo voy" ], "help": "Elegí pocas. Lo importante es que estén siempre en el mismo lugar y que las mires todos los días.", "min": 1, "max": 4 }, { "id": "momento_revision", "type": "text", "prompt": "¿En qué momento del día vas a revisar tu lista y tu agenda?", "help": "Atarlo a algo que ya hacés ayuda: con el desayuno, al llegar al trabajo, antes de cenar.", "placeholder": "Por ejemplo: todas las mañanas con el primer mate" }, { "id": "tarea", "type": "text", "prompt": "¿Qué tarea venís postergando y te gustaría avanzar esta semana?", "placeholder": "Por ejemplo: ordenar los papeles del banco" }, { "id": "pasos", "type": "list", "prompt": "Dividila en pasos muy chicos y concretos, que puedas hacer en menos de 15 minutos cada uno.", "help": "El primer paso tiene que ser tan chico que dé casi risa. Por ejemplo: «sacar la carpeta del cajón».", "count": 5, "min": 3 }, { "id": "pomodoro", "type": "info", "title": "Bloques de trabajo a tu medida", "content": "La **técnica pomodoro** consiste en trabajar en un bloque con temporizador y después hacer una pausa corta. La versión clásica usa bloques de 25 minutos, pero **podés adaptarla**:\n\n- Si te cuesta arrancar, empezá con **bloques de 10 o 15 minutos**.\n- Al terminar el bloque, **pausa de 5 minutos** de verdad: pararte, moverte, tomar agua.\n- Antes de cada bloque, decidí **un solo paso** de tu lista.\n- Si te llega una idea o un pendiente, **anotalo** y seguí.\n- Después de tres o cuatro bloques, hacé una pausa más larga.\n\nSi estás hiperconcentrado/a, la alarma también te sirve para comer, moverte o pasar a otra cosa." }, { "id": "bloque", "type": "choice", "prompt": "¿Con qué largo de bloque querés empezar?", "options": [ "10 minutos", "15 minutos", "20 minutos", "25 minutos" ], "feedback": { "10 minutos": "Buen punto de partida. Si te resulta fácil, podés ir sumando de a poco.", "15 minutos": "Un buen equilibrio para arrancar sin agobiarte.", "20 minutos": "Bien. Si notás que te cuesta sostenerlo, probá acortarlo sin culpa.", "25 minutos": "Es el bloque clásico. Si se te hace largo, achicarlo también está bien." } }, { "id": "entorno", "type": "checklist", "prompt": "Preparar el entorno: ¿qué vas a hacer antes de empezar un bloque?", "options": [ "Dejar el celular en otro lugar o en silencio", "Cerrar pestañas y notificaciones", "Tener a mano todo lo que necesito", "Avisar que no me interrumpan", "Ponerme auriculares o música sin letra", "Despejar la mesa" ], "min": 1, "max": 4 }, { "id": "cuando_bloque", "type": "text", "prompt": "¿Cuándo vas a hacer tu primer bloque con el primer paso de tu tarea?", "placeholder": "Por ejemplo: mañana a las 18, en la mesa del comedor" }, { "id": "resumen", "type": "reflect", "title": "Tu sistema", "template": "Mis herramientas: {{herramientas}}. Las reviso: {{momento_revision}}. Tarea: {{tarea}}. Pasos: {{pasos}}. Bloques de {{bloque}}. Antes de empezar: {{entorno}}. Primer bloque: {{cuando_bloque}}.", "content": "Si algún día el sistema falla, no significa que vos fallaste: es una señal para ajustarlo. Traé lo que observes a la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-alimentacion-entender', 'Entender la relación con la comida', 'Qué pasa cuando comer se vuelve una preocupación, el ciclo restricción–atracón–compensación y cómo se trabaja en terapia.', 'custom', 'tcc', 'todos', 'cuadros', 15, 320,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando la comida ocupa mucho lugar", "content": "A veces la comida, el cuerpo o el peso empiezan a ocupar gran parte de los pensamientos del día. Puede aparecer culpa después de comer, reglas muy estrictas sobre qué está permitido, momentos en los que sentís que perdés el control, o mucha preocupación por cómo te ves.\n\nSi te reconocés en algo de esto, **no estás solo ni sola**, y no es falta de voluntad. Es algo que se puede entender y trabajar, con ayuda.\n\nEste recurso no reemplaza una evaluación profesional: te ayuda a entender qué suele pasar y a llevar preguntas a tu sesión." }, { "id": "que_es", "type": "info", "title": "Qué es y qué no es", "content": "**Qué es:** una relación con la comida y con el cuerpo que genera sufrimiento, ocupa mucho tiempo mental y empieza a afectar tu salud, tu ánimo o tu vida social.\n\n**Qué no es:**\n\n- No es un capricho ni una forma de llamar la atención.\n- No se ve siempre «desde afuera»: le puede pasar a personas de cualquier cuerpo, edad o género.\n- No se resuelve solo con «comer bien» o con más fuerza de voluntad.\n\nMuchas veces la comida termina siendo una forma de manejar emociones difíciles, de sentir control o de calmar la angustia. Entender esa función es parte del trabajo." }, { "id": "ciclo", "type": "info", "title": "El ciclo que lo mantiene", "content": "Muchas personas quedan atrapadas en un ciclo que se repite:\n\n- **Restricción:** reglas estrictas, saltear comidas o prohibirse alimentos.\n- **Hambre y tensión:** el cuerpo y la mente reclaman. Aparecen pensamientos insistentes sobre la comida.\n- **Atracón o pérdida de control:** comer mucho, rápido, sin disfrutar, a veces a escondidas.\n- **Culpa y compensación:** la culpa empuja a «compensar» o a restringir todavía más.\n\nY vuelta a empezar. Lo importante: **la restricción no es la solución, es parte del motor del ciclo.** Por eso el tratamiento no apunta a «controlarte más», sino a salir del ciclo." }, { "id": "comer_regular", "type": "info", "title": "El valor de comer regularmente", "content": "Uno de los primeros pasos que suelen recomendarse es **comer de forma regular**: varias comidas a lo largo del día, en horarios más o menos previsibles, sin pasar muchas horas sin comer.\n\n¿Por qué ayuda?\n\n- Le baja la intensidad al hambre acumulada, que es una de las chispas del atracón.\n- Le da al cuerpo y a la mente una señal de que la comida va a estar.\n- Ordena el día y reduce la cantidad de decisiones difíciles.\n\nNo se trata de contar ni de pesar nada. Se trata de **regularidad**. El plan concreto conviene armarlo con tu equipo de salud." }, { "id": "equipo", "type": "info", "title": "Cómo se trabaja en terapia", "content": "El tratamiento de las dificultades con la alimentación **suele ser en equipo**: psicólogo o psicóloga, médico o médica, y nutricionista. Cada uno cuida una parte, y se comunican entre sí.\n\nEn terapia (por ejemplo, con TCC) se suele trabajar en:\n\n- Registrar qué comés y qué pasa alrededor: emociones, situaciones, pensamientos.\n- Pasar de reglas rígidas a una alimentación regular y flexible.\n- Entender qué emociones se mezclan con la comida y buscar otras formas de manejarlas.\n- Revisar la preocupación por el cuerpo y la autocrítica.\n\nVas a tu ritmo. Lo que se acuerda en sesión se revisa juntos." }, { "id": "seguridad", "type": "info", "title": "Cuándo pedir ayuda ya", "content": "Algunas señales del cuerpo necesitan **consulta médica urgente**, aunque te parezca que «no es para tanto»:\n\n- Desmayos o sensación de que te vas a desmayar.\n- Palpitaciones, latidos muy rápidos o irregulares, o dolor en el pecho.\n- Mareos fuertes, mucha debilidad o confusión.\n- Vómitos frecuentes o no poder retener líquidos.\n\nSi te pasa algo así, o si sentís que estás en crisis o tenés pensamientos de hacerte daño, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "mito_voluntad", "type": "choice", "prompt": "Verdadero o falso: «Si tuviera más fuerza de voluntad, podría controlar lo que como».", "options": [ "Verdadero", "Falso" ], "feedback": { "Verdadero": "**Es una idea muy común, pero no es así.** Muchas veces el problema no es la falta de control sino el exceso de reglas: la restricción alimenta el hambre y la tensión, y eso empuja al atracón. Más control suele hacer el ciclo más fuerte.", "Falso": "**Exacto.** No es una cuestión de voluntad. La restricción es parte del motor del ciclo, y salir de él tiene más que ver con comer regularmente y con entender qué emociones se mezclan con la comida." } }, { "id": "mito_saltear", "type": "choice", "prompt": "Si ayer comiste mucho, ¿qué suele ayudar más hoy?", "options": [ "Saltear comidas para compensar", "Volver a tus comidas regulares", "Comer lo menos posible todo el día" ], "feedback": { "Saltear comidas para compensar": "**Se entiende el impulso, pero suele sostener el ciclo.** Saltear comidas aumenta el hambre y la tensión, y eso hace más probable otro atracón. Lo que más ayuda es volver a la regularidad.", "Volver a tus comidas regulares": "**Sí.** Volver a tu ritmo habitual, sin castigo, es lo que corta el ciclo. Un día difícil no borra lo que venís trabajando.", "Comer lo menos posible todo el día": "**Es una forma de restricción, y la restricción es parte del motor del ciclo.** Lo que más ayuda es volver a tus comidas regulares, sin compensar." } }, { "id": "mito_cuerpo", "type": "choice", "prompt": "¿Se puede saber si alguien tiene dificultades con la comida mirando su cuerpo?", "options": [ "Sí, se nota", "No, no siempre se nota" ], "feedback": { "Sí, se nota": "**No necesariamente.** Las dificultades con la alimentación aparecen en personas de todos los cuerpos. Por eso nadie debería quedarse sin ayuda porque «no se le nota».", "No, no siempre se nota": "**Así es.** Le puede pasar a cualquier persona, con cualquier cuerpo. Lo que importa es el sufrimiento y cómo afecta tu vida, no cómo te ves." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Registrá** tus comidas y lo que pasa alrededor (qué sentías, dónde estabas), sin contar nada. En esta sección tenés una práctica para hacerlo.\n- **Apuntá a la regularidad**, aunque al principio cueste.\n- **Tratate con amabilidad** después de un día difícil: la culpa no ayuda a salir del ciclo.\n- **Anotá preguntas** para tu psicólogo, tu médico o tu nutricionista.\n- **Contale a alguien de confianza** cómo estás, si podés.\n\nNo hace falta hacerlo todo a la vez. Un paso por vez." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de este recurso? ¿Algo que quieras hablar en tu próxima sesión?", "placeholder": "Me llevo… / Quiero preguntar…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "{{me_llevo}}", "content": "Gracias por darte este tiempo. Entender lo que pasa ya es un paso. Cuando toques «Terminar», queda guardado y lo podés compartir en tu próxima sesión." } ]$steps$::jsonb),
  ('cuadro-alimentacion-practica', 'Mi registro de comidas y emociones', 'Registrá una comida y lo que pasaba alrededor, sin contar nada, y esbozá un plan de comidas regulares para revisar en sesión.', 'custom', 'tcc', 'todos', 'cuadros', 12, 321,
   $steps$[ { "id": "intro", "type": "info", "title": "Un registro amable", "content": "Vas a registrar **una comida** (la última, o una que te haya resultado difícil) y lo que pasaba alrededor: dónde estabas, qué sentías, qué pensabas.\n\n**No vas a contar ni a pesar nada.** El objetivo no es juzgar lo que comiste, sino conocer mejor tus patrones para trabajarlos en sesión.\n\nAl final vas a esbozar un plan de comidas regulares para revisar con tu psicólogo y, si tenés, con tu nutricionista." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si en estos días tuviste **desmayos, palpitaciones, dolor en el pecho, mareos fuertes o vómitos frecuentes**, consultá a un médico o una médica cuanto antes: eso es prioridad.\n\nSi sentís que estás en crisis o con riesgo de hacerte daño, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi en algún momento este registro te angustia mucho, podés frenar y retomarlo después o en sesión." }, { "id": "momento", "type": "choice", "prompt": "¿Qué comida vas a registrar?", "options": [ "Desayuno", "Almuerzo", "Merienda", "Cena", "Una colación", "Otro momento" ] }, { "id": "situacion", "type": "text", "prompt": "¿Dónde estabas, con quién y qué venía pasando antes de comer?", "placeholder": "Por ejemplo: en casa, sola, después de una discusión…" }, { "id": "emociones_antes", "type": "checklist", "prompt": "¿Qué sentías antes de comer? Marcá las que quieras.", "options": [ "Hambre", "Tranquilidad", "Ansiedad", "Tristeza", "Enojo", "Aburrimiento", "Cansancio", "Soledad", "Culpa", "No sé bien" ], "min": 1 }, { "id": "hambre", "type": "scale", "prompt": "¿Cuánta hambre tenías antes de comer?", "min": 0, "max": 10, "min_label": "Nada de hambre", "max_label": "Muchísima hambre" }, { "id": "horas_sin_comer", "type": "choice", "prompt": "Antes de esta comida, ¿habías pasado mucho tiempo sin comer?", "options": [ "No, venía comiendo regularmente", "Sí, bastante tiempo", "No me acuerdo" ], "feedback": { "No, venía comiendo regularmente": "**Bien.** La regularidad ayuda a que el hambre no se acumule.", "Sí, bastante tiempo": "**Es un dato valioso.** Pasar mucho tiempo sin comer aumenta el hambre y la tensión, y puede hacer más difícil la comida siguiente. Es algo para tener en cuenta en tu plan.", "No me acuerdo": "**Está bien.** Con el tiempo, registrar seguido ayuda a ver estos patrones con más claridad." } }, { "id": "despues", "type": "text", "prompt": "¿Cómo te sentiste después y qué pensamientos aparecieron?", "placeholder": "Por ejemplo: alivio, culpa, «ya arruiné el día»…" }, { "id": "plan_info", "type": "info", "title": "Un plan de comidas regulares", "content": "Ahora vas a esbozar en qué momentos del día podrías comer de forma regular. Muchas personas apuntan a **varias comidas repartidas en el día**, sin pasar demasiadas horas sin comer.\n\nEs un **borrador para revisar con tu profesional**, no una dieta ni una regla nueva. No hace falta que sea perfecto: anotá horarios aproximados que te resulten posibles." }, { "id": "plan_horarios", "type": "list", "prompt": "¿En qué momentos del día podrías comer? Anotá un momento y horario aproximado por renglón.", "help": "Por ejemplo: «Desayuno, antes de salir», «Merienda, al volver del trabajo».", "count": 6, "min": 3 }, { "id": "obstaculo", "type": "text", "prompt": "¿Qué podría hacerte difícil sostener este plan? ¿Qué te ayudaría?", "placeholder": "Por ejemplo: no tengo tiempo al mediodía; me ayudaría llevar algo preparado" }, { "id": "resumen", "type": "reflect", "title": "Para revisar en sesión", "template": "Registré: {{momento}}. Antes sentía: {{emociones_antes}}. Contexto: {{situacion}}. Después: {{despues}}. Mi borrador de comidas regulares: {{plan_horarios}}. Posible obstáculo: {{obstaculo}}.", "content": "Llevá esto a tu próxima sesión para revisarlo juntos, y con tu nutricionista si tenés. **Lo que hiciste hoy es información, no un examen.** Podés repetir este registro las veces que quieras." } ]$steps$::jsonb),
  ('cuadro-autoestima-entender', 'Entender la autoestima', 'Qué es la autoestima, cómo la sostienen la autocrítica, las creencias de fondo y la comparación, y por qué la autocompasión ayuda.', 'custom', 'tcc', 'todos', 'cuadros', 14, 322,
   $steps$[ { "id": "intro", "type": "info", "title": "Cómo te tratás por dentro", "content": "La **autoestima** es la forma en que te mirás, te valorás y te tratás a vos mismo o a vos misma. No es algo fijo: cambia con lo que vivís, con cómo te hablás y con lo que aprendiste de chico o de chica.\n\nCuando la autoestima está baja, es común sentir que no alcanzás, que los demás valen más, o que cualquier error confirma que «algo está mal en vos».\n\nEste recurso te ayuda a entender cómo se mantiene esa mirada y qué se puede hacer." }, { "id": "que_es", "type": "info", "title": "Qué es y qué no es", "content": "**Tener una autoestima sana no es:**\n\n- Sentirte genial todo el tiempo.\n- Creer que sos mejor que los demás.\n- No tener nunca dudas ni inseguridades.\n\n**Sí es:**\n\n- Poder reconocer tus cualidades y tus límites, sin exagerar ninguno.\n- Tratarte con respeto también cuando te equivocás.\n- Sentir que valés como persona, más allá de lo que logres.\n\nLa baja autoestima no es un defecto de personalidad: es un patrón aprendido, y lo aprendido se puede revisar." }, { "id": "autocritica", "type": "info", "title": "La voz crítica", "content": "Muchas personas tienen una **voz interna muy crítica**: «sos un desastre», «otra vez lo arruinaste», «nadie te va a querer así».\n\nEsa voz muchas veces apareció para protegerte (para que no te equivoques, para que no te rechacen), pero con el tiempo **lastima más de lo que ayuda**. La autocrítica dura no suele motivar: suele dar más miedo, más vergüenza y más ganas de evitar.\n\nUna pista: **¿le hablarías así a alguien que querés?** Si la respuesta es no, vale la pena revisar ese tono." }, { "id": "creencias", "type": "info", "title": "Las creencias de fondo", "content": "En TCC se habla de **creencias nucleares**: ideas profundas sobre uno mismo, como «no soy suficiente», «no soy querible» o «soy un fracaso». Suelen formarse temprano, a partir de experiencias difíciles.\n\nEstas creencias funcionan como **anteojos**: hacen que notes lo que las confirma y pases por alto lo que las contradice. Si sacás una buena nota, «fue suerte»; si te equivocás, «¿viste? soy un desastre».\n\nNo son verdades: son **hipótesis aprendidas**. En terapia se revisan con calma, buscando la evidencia que los anteojos esconden." }, { "id": "comparacion", "type": "info", "title": "La trampa de la comparación", "content": "Compararse es humano, pero cuando la autoestima está baja la comparación suele ser **injusta**: comparás tu interior (tus dudas, tus días malos) con el exterior de los demás (lo que muestran).\n\nLas redes sociales hacen esto más fácil: vemos fotos elegidas y momentos editados, no la vida completa.\n\nAlgunas preguntas útiles:\n\n- ¿Estoy comparando lo mismo con lo mismo?\n- ¿Qué no estoy viendo de la vida de esa persona?\n- ¿Me sirve esta comparación, o solo me hace sentir peor?" }, { "id": "autocompasion", "type": "info", "title": "La autocompasión como alternativa", "content": "La **autocompasión** es tratarte con la misma amabilidad que le tendrías a un buen amigo o una buena amiga que la está pasando mal. Tiene tres partes:\n\n- **Atención:** notar que estás sufriendo, sin exagerarlo ni taparlo.\n- **Humanidad compartida:** recordar que equivocarse y sentirse inseguro les pasa a todas las personas.\n- **Amabilidad:** hablarte con calidez en lugar de con desprecio.\n\nNo es conformismo ni lástima: la investigación muestra que tratarse con amabilidad **ayuda a hacerse cargo** de los errores y a seguir intentando." }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "En terapia se suele trabajar en:\n\n- **Reconocer** la voz crítica y los momentos en que aparece.\n- **Revisar** las creencias de fondo y buscar evidencia más completa.\n- **Registrar** logros y cualidades, para entrenar la mirada a ver también lo que funciona.\n- **Practicar** la autocompasión y otras formas de hablarte.\n- **Animarte** a hacer cosas que venís evitando por miedo a no estar a la altura.\n\nEs un proceso gradual. No se trata de pensar «positivo» a la fuerza, sino de mirarte de forma más justa." }, { "id": "seguridad", "type": "info", "title": "Si te sentís muy mal", "content": "A veces la autocrítica se vuelve tan fuerte que aparecen pensamientos de que no valés la pena o de hacerte daño.\n\nSi te pasa, **no estás solo ni sola, y merecés ayuda ya**: pedila a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nY contáselo también a tu psicólogo en la próxima sesión, o antes si podés." }, { "id": "mito_autocompasion", "type": "choice", "prompt": "Verdadero o falso: «Si soy amable conmigo, me voy a volver vago y no voy a mejorar».", "options": [ "Verdadero", "Falso" ], "feedback": { "Verdadero": "**Es un miedo muy común, pero la evidencia dice lo contrario.** Las personas que se tratan con amabilidad suelen hacerse más cargo de sus errores y volver a intentar, porque equivocarse no les resulta tan amenazante.", "Falso": "**Exacto.** La autocompasión no es conformismo: ayuda a aprender de los errores sin hundirse en la vergüenza, y eso hace más fácil seguir intentando." } }, { "id": "mito_logros", "type": "choice", "prompt": "¿Qué crees que sostiene mejor la autoestima a largo plazo?", "options": [ "Lograr cada vez más cosas", "Tratarte con respeto, logres o no", "Que los demás te aprueben" ], "feedback": { "Lograr cada vez más cosas": "**Los logros ayudan, pero si tu valor depende solo de ellos, la autoestima queda frágil:** cada error se vive como una amenaza. Una base más estable es tratarte con respeto también cuando las cosas no salen.", "Tratarte con respeto, logres o no": "**Sí.** Una autoestima más estable no depende de rendir siempre: se apoya en cómo te tratás en los buenos y en los malos momentos.", "Que los demás te aprueben": "**La aprobación de otros se siente bien, pero no la controlás**, y depender de ella deja la autoestima en manos ajenas. Una base más estable es cómo te tratás vos." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Registrá** cada día algo que hiciste bien o una cualidad que mostraste, por chica que sea. En esta sección tenés una práctica para hacerlo.\n- **Notá** cuándo aparece la voz crítica y qué dice.\n- **Probá** responderle como le hablarías a alguien que querés.\n- **Cuidá** lo que consumís en redes si notás que te deja peor.\n- **Anotá** situaciones para trabajar en tu próxima sesión." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de este recurso?", "placeholder": "Me llevo…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "{{me_llevo}}", "content": "Gracias por darte este tiempo. Mirarte con más justicia es un aprendizaje, y se practica de a poco." } ]$steps$::jsonb),
  ('cuadro-autoestima-practica', 'Logros, cualidades y la voz de un amigo', 'Registrá logros y cualidades, y practicá responderle a tu voz crítica como le hablarías a alguien que querés.', 'custom', 'tcc', 'todos', 'cuadros', 12, 323,
   $steps$[ { "id": "intro", "type": "info", "title": "Entrenar otra mirada", "content": "Cuando la autoestima está baja, la mente se especializa en ver lo que falta. Esta práctica tiene dos partes:\n\n- **Registrar logros y cualidades**, para entrenar la mirada a ver también lo que sí funciona.\n- **Responderle a la voz crítica** con la voz de un amigo o una amiga.\n\nNo hace falta creerte todo lo que escribas. Alcanza con intentarlo con honestidad." }, { "id": "seguridad", "type": "info", "title": "Si te sentís muy mal", "content": "Si mientras hacés esto aparecen pensamientos de que no valés la pena o de hacerte daño, frená y **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nPodés retomar esta práctica otro día o hacerla en sesión." }, { "id": "logros", "type": "list", "prompt": "Anotá cosas que hiciste esta semana y te costaron, aunque sean chicas.", "help": "Cuentan las cosas cotidianas: levantarte en un día difícil, pedir ayuda, terminar algo pendiente, cuidar a alguien.", "count": 3, "min": 1 }, { "id": "cualidades", "type": "checklist", "prompt": "¿Qué cualidades mostraste en esas situaciones? Marcá las que veas.", "options": [ "Esfuerzo", "Paciencia", "Valentía", "Generosidad", "Honestidad", "Constancia", "Humor", "Cuidado por otros", "Creatividad", "Responsabilidad" ], "min": 1 }, { "id": "otros_ven", "type": "text", "prompt": "¿Qué cualidad tuya diría alguien que te quiere, aunque a vos te cueste verla?", "placeholder": "Mi amiga diría que soy…", "optional": true }, { "id": "voz_intro", "type": "info", "title": "La voz crítica y la voz de un amigo", "content": "Ahora pensá en una situación reciente en la que te criticaste con dureza. Vas a escribir **qué te dijo la voz crítica**, tal cual, y después vas a imaginar qué te diría **un buen amigo o una buena amiga** que te quiere y conoce lo que estás pasando.\n\nLa voz de un amigo no miente ni te dice que todo está perfecto: **reconoce lo difícil, te recuerda que es humano equivocarse y te habla con cariño.**" }, { "id": "situacion", "type": "text", "prompt": "¿Qué pasó? Describí la situación brevemente.", "placeholder": "Por ejemplo: me olvidé de entregar algo en el trabajo" }, { "id": "voz_critica", "type": "text", "prompt": "¿Qué te dijo la voz crítica?", "placeholder": "Por ejemplo: «Sos un desastre, siempre lo mismo»" }, { "id": "intensidad_antes", "type": "scale", "prompt": "¿Qué tan mal te hace sentir esa frase ahora?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo" }, { "id": "voz_amigo", "type": "text", "prompt": "¿Qué te diría un amigo o una amiga que te quiere, sobre esto mismo?", "help": "Probá empezar con algo como: «Tiene sentido que te sientas así, porque…», «A cualquiera le puede pasar…», «Lo que sí hiciste bien fue…».", "placeholder": "Tiene sentido que te sientas así…" }, { "id": "intensidad_despues", "type": "scale", "prompt": "Después de leer la voz de tu amigo, ¿qué tan mal te hace sentir la frase crítica?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo" }, { "id": "resumen", "type": "reflect", "title": "Lo que registraste", "template": "Esta semana logré: {{logros}}. Mostré: {{cualidades}}. Cuando la voz crítica me dijo «{{voz_critica}}», la voz de un amigo me respondió: «{{voz_amigo}}».", "content": "Si la incomodidad bajó aunque sea un poco, es una señal de que esta voz se puede entrenar. Si no bajó, también está bien: **es una práctica, no un examen.** Podés repetirla cada vez que la voz crítica aparezca fuerte, y traerla a sesión." } ]$steps$::jsonb),
  ('cuadro-pareja-entender', 'Entender los problemas de pareja', 'Patrones de comunicación que dañan el vínculo, cómo pedir lo que necesitás y por qué la violencia no es un problema de comunicación.', 'custom', 'tcc', 'todos', 'cuadros', 15, 324,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando el vínculo duele", "content": "Todas las parejas tienen desacuerdos. Discutir no significa que la relación esté mal. Lo que suele marcar la diferencia es **cómo** se discute, cómo se repara después y si las dos personas se sienten seguras y respetadas.\n\nEste recurso te ayuda a reconocer algunos patrones frecuentes, a pensar en tus necesidades y a distinguir un conflicto de una situación de violencia.\n\nSirve para cualquier tipo de pareja, y muchas ideas también aplican a otros vínculos cercanos." }, { "id": "que_es", "type": "info", "title": "Qué es y qué no es", "content": "**Un conflicto de pareja es:** un desacuerdo entre dos personas que se respetan, donde las dos pueden decir lo que piensan sin miedo.\n\n**No es lo mismo que:**\n\n- **Violencia:** cuando una persona controla, amenaza, humilla, aísla, lastima o da miedo a la otra.\n- **Incompatibilidad total:** a veces el conflicto muestra que se quieren cosas muy distintas, y eso también merece hablarse.\n\nCuando hay conflicto, se puede trabajar la comunicación. **Cuando hay violencia, lo primero es la seguridad**, y eso lo vemos más adelante." }, { "id": "patrones", "type": "info", "title": "Cuatro patrones que desgastan", "content": "La investigación sobre parejas describe cuatro patrones que, cuando se repiten, desgastan mucho el vínculo:\n\n- **Críticas:** atacar a la persona en lugar de hablar de una conducta. «Sos un egoísta» en lugar de «me molestó que no avisaras».\n- **Defensividad:** responder a cada queja con excusas o contraataques, sin escuchar.\n- **Desprecio:** burlas, sarcasmo, gestos de superioridad. Es el patrón más dañino.\n- **Evasión:** cerrarse, irse, no contestar, «hacer la pared».\n\nCasi todas las personas caemos en alguno a veces. Reconocerlos es el primer paso para cambiarlos." }, { "id": "alternativas", "type": "info", "title": "Qué hacer en su lugar", "content": "Para cada patrón hay una alternativa:\n\n- **En vez de criticar:** hablá de lo que sentís y de una situación concreta. «Yo siento… cuando… necesito…».\n- **En vez de defenderte:** buscá la parte de razón que tiene el otro y hacete cargo de tu parte.\n- **En vez de despreciar:** recordá lo que valorás de esa persona y expresalo.\n- **En vez de evadir:** si te desbordás, pedí una pausa y acordá cuándo retomar. «Necesito veinte minutos para calmarme, después seguimos».\n\nNo se trata de no discutir, sino de discutir sin lastimar." }, { "id": "necesidades", "type": "info", "title": "Necesidades y pedidos claros", "content": "Muchas discusiones se repiten porque detrás de la queja hay una **necesidad** que no se dice: sentirse tenido en cuenta, tener tiempo juntos, sentir apoyo, tener espacio propio.\n\nUn **pedido claro** es concreto, posible y dicho en positivo:\n\n- Poco claro: «Nunca me das bola».\n- Más claro: «Me gustaría que el domingo a la tarde hagamos algo juntos, sin celulares».\n\nPedir no garantiza que el otro diga que sí, pero le da una oportunidad real de responder. En esta sección tenés una práctica para preparar una conversación así." }, { "id": "violencia", "type": "info", "title": "La violencia no es un problema de comunicación", "content": "Algunas señales de violencia en la pareja:\n\n- Te da **miedo** cómo va a reaccionar.\n- Controla tu celular, tu plata, tu ropa o con quién te ves.\n- Te humilla, te insulta o te amenaza, en privado o delante de otros.\n- Te aleja de tu familia o tus amistades.\n- Te empuja, golpea, rompe cosas o te obliga a algo sexual que no querés.\n\nNada de esto es tu culpa ni se arregla «comunicándote mejor». **Si te pasa, lo primero es tu seguridad.** No hace falta que estés segura o seguro de que «es violencia» para pedir ayuda: contáselo a tu psicólogo o a alguien de confianza." }, { "id": "seguridad", "type": "info", "title": "Si estás en peligro", "content": "Si estás en peligro ahora, si alguien te lastimó o te amenaza, o si sentís que estás en crisis, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi convivís con la persona, pensá en un lugar y una persona a los que puedas ir, y hablalo con tu psicólogo.\n\nSi te preocupa que alguien vea esta app en tu celular, cuidá tu privacidad: podés cerrar sesión al terminar." }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "Los temas de pareja se pueden trabajar **en terapia individual**, entendiendo tus patrones, tus necesidades y cómo te gustaría vincularte, o a veces **en terapia de pareja**, si las dos personas quieren y no hay violencia.\n\nSe suele trabajar en:\n\n- Reconocer los patrones que se repiten en las discusiones.\n- Aprender a expresar emociones y pedidos de forma clara.\n- Practicar la escucha activa.\n- Reparar después de una discusión.\n- Revisar si el vínculo es seguro y te hace bien." }, { "id": "mito_pelear", "type": "choice", "prompt": "Verdadero o falso: «Las parejas que funcionan bien no discuten nunca».", "options": [ "Verdadero", "Falso" ], "feedback": { "Verdadero": "**Es un mito frecuente.** Las parejas que funcionan bien también discuten. La diferencia está en cómo lo hacen: con respeto, sin desprecio, y con capacidad de reparar después.", "Falso": "**Así es.** Los desacuerdos son parte de cualquier vínculo. Lo importante es discutir sin lastimar y poder reparar después." } }, { "id": "mito_celos", "type": "choice", "prompt": "Si tu pareja revisa tu celular y controla con quién hablás, ¿qué es?", "options": [ "Una prueba de amor", "Una señal de control que conviene tomar en serio", "Algo normal en toda pareja" ], "feedback": { "Una prueba de amor": "**Es una idea muy instalada, pero el control no es amor.** Revisar el celular o decidir con quién hablás son señales de control. Vale la pena hablarlo con tu psicólogo o con alguien de confianza.", "Una señal de control que conviene tomar en serio": "**Sí.** El control no es una forma de cuidado. Si te pasa, no es tu culpa, y podés hablarlo con tu psicólogo o con alguien de confianza. Si sentís miedo, priorizá tu seguridad.", "Algo normal en toda pareja": "**Pasa seguido, pero no es sano.** Revisar el celular o controlar con quién hablás son señales de control. Vale la pena tomarlo en serio y hablarlo con tu psicólogo." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Observá** qué patrones aparecen en tus discusiones, en vos y en el otro.\n- **Pensá** qué necesidad hay detrás de tu queja más frecuente.\n- **Prepará** una conversación con «Yo siento… cuando… necesito…». En esta sección tenés una práctica.\n- **Pedí una pausa** cuando te desbordes, y acordá cuándo retomar.\n- **Si hay miedo o violencia,** no hace falta prepararse para hablar: priorizá tu seguridad y contáselo a tu psicólogo." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de este recurso?", "placeholder": "Me llevo…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "{{me_llevo}}", "content": "Gracias por darte este tiempo. Merecés vínculos en los que te sientas con seguridad y respeto." } ]$steps$::jsonb),
  ('cuadro-pareja-practica', 'Preparar una conversación difícil', 'Prepará lo que querés decir con «Yo siento… cuando… necesito…» y repasá cómo escuchar al otro de verdad.', 'custom', 'tcc', 'todos', 'cuadros', 13, 325,
   $steps$[ { "id": "intro", "type": "info", "title": "Antes de hablar", "content": "Las conversaciones difíciles salen mejor cuando se preparan. Vas a:\n\n- Elegir **un tema** concreto.\n- Armar una frase con **«Yo siento… cuando… necesito…»**.\n- Repasar cómo practicar la **escucha activa** cuando hable el otro.\n- Elegir un buen momento.\n\nSirve para la pareja y también para otros vínculos cercanos." }, { "id": "seguridad", "type": "info", "title": "Primero, tu seguridad", "content": "Esta práctica es para **conflictos entre personas que se respetan**. Si la otra persona te da miedo, te controla, te amenaza o te lastimó, **no hace falta que te prepares para hablar con ella**: lo primero es tu seguridad. Contáselo a tu psicólogo o a alguien de confianza.\n\nSi estás en peligro ahora o sentís que estás en crisis, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "es_seguro", "type": "choice", "prompt": "¿Te sentís con seguridad para tener esta conversación con esa persona?", "options": [ "Sí", "No estoy seguro o segura", "No" ], "feedback": { "Sí": "**Bien.** Seguí adelante con la preparación.", "No estoy seguro o segura": "**Esa duda es importante.** Podés seguir preparando la conversación, pero antes de tenerla, hablalo con tu psicólogo. Si en algún momento sentís miedo, priorizá tu seguridad.", "No": "**Gracias por decirlo.** En ese caso, lo más importante no es cómo decirlo, sino cuidarte. Te recomendamos no tener esta conversación a solas y hablarlo con tu psicólogo o con alguien de confianza. Si estás en peligro, pedí ayuda ya." } }, { "id": "tema", "type": "text", "prompt": "¿De qué tema querés hablar? Elegí uno solo y concreto.", "placeholder": "Por ejemplo: cómo nos repartimos las tareas de la casa" }, { "id": "siento", "type": "text", "prompt": "Yo siento… ¿Qué emoción te genera esto?", "help": "Hablá de tu emoción, no de lo que el otro «es». Por ejemplo: cansancio, tristeza, enojo, soledad, preocupación.", "placeholder": "Me siento…" }, { "id": "cuando", "type": "text", "prompt": "…cuando… ¿Qué situación concreta pasa?", "help": "Describí lo que pasa como lo vería una cámara, sin «siempre» ni «nunca». Por ejemplo: «cuando llego del trabajo y la cocina está sin ordenar».", "placeholder": "Cuando…" }, { "id": "necesito", "type": "text", "prompt": "…necesito… ¿Qué pedido concreto y posible querés hacer?", "help": "Un pedido en positivo y concreto. Por ejemplo: «necesito que nos repartamos los días para cocinar y ordenar».", "placeholder": "Necesito…" }, { "id": "frase", "type": "reflect", "title": "Tu frase", "template": "Me siento {{siento}} cuando {{cuando}}. Necesito {{necesito}}.", "content": "Leela en voz alta. ¿Suena a una crítica o a algo que te pasa a vos? Si suena a ataque, podés tocar «Atrás» y ajustarla." }, { "id": "escucha", "type": "info", "title": "Escucha activa", "content": "Después de decir lo tuyo, **le toca al otro**. Escuchar de verdad es tan importante como hablar bien:\n\n- **Escuchá para entender,** no para preparar tu respuesta.\n- **Resumí** lo que entendiste: «Te entiendo que llegás muy cansado y no te dan ganas de ordenar, ¿es así?».\n- **Validá** lo que tenga sentido: «Tiene sentido que estés cansado».\n- **Preguntá** antes de suponer: «¿Qué te ayudaría a vos?».\n\nValidar no es darle la razón en todo: es mostrar que entendés cómo lo vive." }, { "id": "escucha_plan", "type": "checklist", "prompt": "¿Qué te comprometés a hacer mientras el otro habla?", "options": [ "No interrumpir", "Resumir lo que entendí", "Validar lo que tenga sentido", "Preguntar antes de suponer", "Pedir una pausa si me desbordo", "Evitar el sarcasmo y las burlas" ], "min": 1 }, { "id": "momento", "type": "text", "prompt": "¿Cuándo y dónde podría ser un buen momento para hablar?", "help": "Mejor un momento tranquilo, sin apuro y sin otras personas. Evitá hacerlo en medio de una discusión o con alguien muy cansado.", "placeholder": "Por ejemplo: el sábado a la mañana, tomando mate" }, { "id": "resumen", "type": "reflect", "title": "Tu plan para la conversación", "template": "Tema: {{tema}}. Voy a decir: «Me siento {{siento}} cuando {{cuando}}. Necesito {{necesito}}». Mientras el otro habla, me comprometo a: {{escucha_plan}}. Momento: {{momento}}.", "content": "No podés controlar cómo va a responder la otra persona, pero sí cómo te expresás vos. Si la conversación se pone tensa, pedí una pausa y acordá cuándo retomar. Después, contá en sesión cómo te fue." } ]$steps$::jsonb),
  ('cuadro-regulacion-entender', 'Entender las emociones intensas', 'Para qué sirven las emociones, la ventana de tolerancia y cómo una emoción lleva a la acción, según la DBT.', 'custom', 'dbt', 'todos', 'cuadros', 15, 326,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando las emociones desbordan", "content": "Algunas personas sienten las emociones **muy rápido, muy fuerte y por mucho tiempo**. Un comentario chico puede disparar un enojo enorme, o una tristeza que tarda en irse. Después, a veces, aparece la vergüenza por cómo reaccionaste.\n\nSi te pasa, no es que estés «exagerando» ni que haya algo roto en vos. Hay personas con un sistema emocional más sensible, y hay **habilidades concretas** para manejarlo mejor.\n\nEste recurso te ayuda a entender qué está pasando." }, { "id": "funcion", "type": "info", "title": "Para qué sirven las emociones", "content": "Las emociones no son el problema: **cumplen funciones**.\n\n- **Te avisan** de algo importante: el miedo de un peligro, la tristeza de una pérdida, el enojo de una injusticia.\n- **Te preparan para actuar:** el cuerpo se activa para huir, defenderte o buscar consuelo.\n- **Comunican** a los demás lo que te pasa, muchas veces sin palabras.\n\nLa dificultad aparece cuando la emoción es muy intensa para la situación, dura demasiado, o te lleva a hacer cosas que después lamentás. Regular no es dejar de sentir: es **poder sentir sin que la emoción decida todo por vos**." }, { "id": "que_no_es", "type": "info", "title": "Qué es y qué no es regularse", "content": "**Regular las emociones no es:**\n\n- Reprimirlas o hacer como que no existen.\n- Estar tranquilo o tranquila todo el tiempo.\n- «Controlarte» a la fuerza.\n\n**Sí es:**\n\n- Notar qué estás sintiendo y ponerle nombre.\n- Bajar la intensidad cuando es demasiado alta.\n- Elegir qué hacer con lo que sentís, de acuerdo con lo que te importa.\n\nEs una habilidad, y como toda habilidad, **se aprende con práctica**." }, { "id": "ventana", "type": "info", "title": "La ventana de tolerancia", "content": "Imaginá una **ventana**: dentro de ella, podés sentir emociones (incluso fuertes) y seguir pensando con claridad.\n\n- **Por arriba de la ventana:** demasiada activación. Ansiedad intensa, enojo que desborda, impulsos fuertes, sensación de que no podés pensar.\n- **Por debajo de la ventana:** muy poca activación. Sentirte vacío o vacía, desconectado, «apagado», sin energía.\n\nEl estrés, el cansancio o experiencias difíciles pueden **achicar** la ventana. Las habilidades que se aprenden en terapia ayudan a volver a ella y, con el tiempo, a **agrandarla**." }, { "id": "modelo", "type": "info", "title": "De la vulnerabilidad a la acción", "content": "La DBT propone mirar una emoción como una cadena:\n\n- **Vulnerabilidad:** cosas que te dejan más sensible ese día: dormir mal, no comer, estar enfermo, mucho estrés acumulado.\n- **Disparador:** algo que pasa, afuera o adentro (un recuerdo, un pensamiento).\n- **Interpretación:** lo que pensás sobre lo que pasó.\n- **Emoción:** lo que sentís en el cuerpo y en la mente.\n- **Impulso y acción:** lo que te dan ganas de hacer, y lo que hacés.\n- **Consecuencias:** lo que pasa después.\n\nCada eslabón es un **punto donde podés intervenir**. Por ejemplo, cuidar el sueño baja la vulnerabilidad; frenar antes de actuar cambia la acción." }, { "id": "no_peligrosas", "type": "info", "title": "Intensas, pero no peligrosas", "content": "Una emoción intensa puede sentirse insoportable, como si nunca fuera a terminar. Pero **las emociones, por sí mismas, no son peligrosas**: suben, llegan a un pico y bajan, como una ola. Lo que a veces sí puede ser riesgoso es lo que hacemos para sacárnoslas de encima rápido.\n\nAl mismo tiempo, **son agotadoras**. Vivir con emociones muy intensas cansa, y es entendible que quieras alivio.\n\nPor eso las habilidades DBT apuntan a dos cosas: **atravesar la ola** sin empeorar las cosas, y **bajar la vulnerabilidad** para que las olas sean menos frecuentes." }, { "id": "seguridad", "type": "info", "title": "Si estás en crisis", "content": "Si la emoción es tan fuerte que sentís que podés hacerte daño, o tenés pensamientos de no querer vivir, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nNo tenés que atravesarlo sola ni solo. Contáselo también a tu psicólogo." }, { "id": "terapia", "type": "info", "title": "Cómo se trabaja en terapia", "content": "En terapia (por ejemplo, con DBT) se suele trabajar en cuatro grupos de habilidades:\n\n- **Mindfulness:** notar lo que pasa adentro sin juzgarlo.\n- **Tolerancia al malestar:** atravesar una crisis sin empeorarla (por ejemplo, STOP y TIPP).\n- **Regulación emocional:** entender las emociones, bajar la vulnerabilidad y usar la acción opuesta.\n- **Efectividad interpersonal:** pedir lo que necesitás y poner límites cuidando el vínculo.\n\nTambién se usan **registros** para ver la cadena de cada emoción intensa y encontrar dónde intervenir." }, { "id": "mito_reprimir", "type": "choice", "prompt": "Verdadero o falso: «Para regularme tengo que dejar de sentir lo que siento».", "options": [ "Verdadero", "Falso" ], "feedback": { "Verdadero": "**Es un error muy común.** Intentar no sentir suele hacer que la emoción vuelva más fuerte. Regularse es poder sentir, ponerle nombre y elegir qué hacer, no apagar la emoción.", "Falso": "**Exacto.** Regular no es reprimir. Es poder sentir sin que la emoción decida todo por vos." } }, { "id": "mito_ola", "type": "choice", "prompt": "Si no hacés nada para sacártela de encima, ¿qué pasa con una emoción muy intensa?", "options": [ "Sigue subiendo para siempre", "Llega a un pico y después baja", "Se vuelve peligrosa" ], "feedback": { "Sigue subiendo para siempre": "**Se siente así, pero no es lo que pasa.** Las emociones funcionan como olas: suben, llegan a un pico y bajan. Saberlo ayuda a atravesarlas.", "Llega a un pico y después baja": "**Sí.** Como una ola. Por eso muchas habilidades DBT apuntan a atravesar el pico sin hacer algo que empeore las cosas.", "Se vuelve peligrosa": "**La emoción en sí no es peligrosa, aunque se sienta muy fuerte.** Lo que puede ser riesgoso es lo que hacemos para escapar de ella. Por eso se aprenden habilidades para atravesarla." } }, { "id": "entre_sesiones", "type": "info", "title": "Qué podés hacer entre sesiones", "content": "- **Cuidá tu vulnerabilidad:** dormir, comer regularmente, moverte un poco y bajar el consumo de alcohol u otras sustancias.\n- **Ponele nombre** a lo que sentís, aunque sea aproximado.\n- **Practicá una habilidad** cuando estés tranquilo o tranquila, para que esté a mano en una crisis. En esta sección tenés una práctica con STOP, TIPP y acción opuesta.\n- **Registrá** una emoción intensa para revisarla en sesión.\n- **Usá Calmarme** cuando lo necesites." }, { "id": "me_llevo", "type": "text", "prompt": "¿Qué te llevás de este recurso?", "placeholder": "Me llevo…" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "{{me_llevo}}", "content": "Gracias por darte este tiempo. Sentir intensamente no es un defecto: es algo con lo que se puede aprender a convivir mejor." } ]$steps$::jsonb),
  ('cuadro-regulacion-practica', 'Habilidades para emociones intensas', 'Practicá STOP, TIPP y la acción opuesta de la DBT, y registrá una emoción intensa para revisarla en sesión.', 'custom', 'dbt', 'todos', 'cuadros', 15, 327,
   $steps$[ { "id": "intro", "type": "info", "title": "Tu caja de herramientas", "content": "Vas a repasar tres habilidades de la DBT y a registrar una emoción intensa reciente:\n\n- **STOP:** frenar antes de actuar por impulso.\n- **TIPP:** bajar rápido la activación del cuerpo.\n- **Acción opuesta:** hacer lo contrario de lo que pide la emoción, cuando esa emoción no te ayuda.\n\nLo ideal es practicarlas **cuando estás con calma**, para que estén a mano cuando las necesites." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si ahora mismo estás en crisis, con riesgo de hacerte daño o con pensamientos de no querer vivir, **pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nEstas habilidades ayudan a atravesar momentos difíciles, pero **no reemplazan la ayuda urgente** cuando hay riesgo." }, { "id": "intensidad_antes", "type": "scale", "prompt": "¿Qué tan intensa es tu emoción en este momento?", "min": 0, "max": 10, "min_label": "Nada intensa", "max_label": "Muy intensa", "maps_to": "emotion_before" }, { "id": "stop", "type": "info", "title": "STOP", "content": "Cuando sentís el impulso de reaccionar ya:\n\n- **S — Pará.** Quedate quieto o quieta un momento. No hagas nada todavía.\n- **T — Tomá distancia.** Respirá. Si podés, alejate un poco de la situación.\n- **O — Observá.** ¿Qué pasa en tu cuerpo? ¿Qué pensás? ¿Qué está pasando afuera?\n- **P — Procedé con atención.** Preguntate: ¿qué me ayudaría ahora, de acuerdo con lo que me importa?\n\nA veces, solo frenar unos segundos ya cambia lo que hacés después." }, { "id": "stop_practica", "type": "timed_info", "title": "Probá STOP ahora", "content": "Pará lo que estés haciendo. Respirá lento, soltando el aire despacio. Observá tu cuerpo: los pies en el piso, los hombros, la mandíbula. Notá qué pensamientos aparecen, sin pelearte con ellos.", "seconds": 60 }, { "id": "tipp", "type": "info", "title": "TIPP: bajar la activación del cuerpo", "content": "Cuando la emoción está muy alta, primero ayuda calmar el cuerpo:\n\n- **T — Temperatura:** mojarte la cara con agua fría puede bajar la activación. **Cuidado:** no lo uses si tenés problemas cardíacos o de presión, o algún trastorno de la alimentación; si tenés dudas, consultá antes a tu médico.\n- **I — Ejercicio intenso:** unos minutos de movimiento fuerte, como caminar rápido o subir escaleras, dentro de lo que tu cuerpo pueda.\n- **P — Respiración pausada:** exhalar más lento de lo que inhalás.\n- **P — Relajación muscular:** tensar un grupo de músculos unos segundos y soltar.\n\nElegí la que te resulte más segura y posible." }, { "id": "respiracion", "type": "timed_info", "title": "Respiración pausada", "content": "Inhalá por la nariz mientras contás hasta cuatro. Exhalá despacio por la boca mientras contás hasta seis. Repetí a tu ritmo. Si te mareás, volvé a respirar normal.", "seconds": 90 }, { "id": "accion_opuesta", "type": "info", "title": "Acción opuesta", "content": "Cada emoción trae un impulso: el miedo empuja a evitar, la tristeza a aislarte, el enojo a atacar. Cuando la emoción **no encaja con los hechos** o seguirla te haría daño, podés hacer **lo opuesto**:\n\n- **Miedo que te hace evitar** algo que no es peligroso: acercarte de a poco.\n- **Tristeza que te aísla:** escribirle a alguien, salir un rato, hacer algo chiquito.\n- **Enojo que te empuja a atacar:** alejarte con amabilidad, bajar la voz, ponerte en el lugar del otro.\n\nNo se trata de fingir: se trata de no dejar que la emoción decida todo." }, { "id": "registro_intro", "type": "info", "title": "Registrar una emoción intensa", "content": "Ahora pensá en una emoción intensa de los últimos días. Vas a registrar la cadena: qué te dejó más sensible, qué la disparó, qué sentiste, qué te dieron ganas de hacer y qué hiciste.\n\nNo hace falta que elijas la peor. Si recordarla te desborda, elegí otra más leve." }, { "id": "vulnerabilidad", "type": "checklist", "prompt": "¿Qué te dejaba más sensible ese día? Marcá las que correspondan.", "options": [ "Dormí mal", "No había comido bien", "Estaba con dolor o enfermo/a", "Mucho estrés acumulado", "Alcohol u otra sustancia", "Nada en particular" ], "min": 1 }, { "id": "disparador", "type": "text", "prompt": "¿Qué pasó? ¿Qué disparó la emoción?", "placeholder": "Por ejemplo: un mensaje que no me contestaron" }, { "id": "emocion", "type": "text", "prompt": "¿Qué emoción sentiste? ¿Dónde la notaste en el cuerpo?", "placeholder": "Por ejemplo: enojo, con calor en la cara y el pecho apretado" }, { "id": "impulso", "type": "text", "prompt": "¿Qué te dieron ganas de hacer, y qué hiciste?", "placeholder": "Tenía ganas de… / Hice…" }, { "id": "habilidad", "type": "choice", "prompt": "La próxima vez, ¿qué habilidad te gustaría probar primero?", "options": [ "STOP", "TIPP", "Acción opuesta", "Cuidar mi vulnerabilidad", "Todavía no sé" ], "feedback": { "STOP": "**Buena elección.** Frenar unos segundos antes de actuar es una de las habilidades más útiles en el momento.", "TIPP": "**Buena elección** cuando la emoción está muy alta. Recordá las precauciones del agua fría y elegí la opción más segura para vos.", "Acción opuesta": "**Buena elección.** Funciona mejor cuando ya bajó un poco la intensidad y podés pensar qué te ayudaría.", "Cuidar mi vulnerabilidad": "**Muy buena elección.** Dormir, comer regularmente y bajar el estrés hace que las olas sean menos frecuentes.", "Todavía no sé": "**Está bien.** Podés probarlas de a una y ver cuál te sirve más. Lo pueden pensar juntos en sesión." } }, { "id": "intensidad_despues", "type": "scale", "prompt": "Y ahora, después de la práctica, ¿qué tan intensa es tu emoción?", "min": 0, "max": 10, "min_label": "Nada intensa", "max_label": "Muy intensa", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Tu registro", "template": "Vulnerabilidad: {{vulnerabilidad}}. Disparador: {{disparador}}. Emoción: {{emocion}}. Impulso y acción: {{impulso}}. La próxima vez voy a probar: {{habilidad}}.", "content": "Llevá este registro a tu próxima sesión: ver la cadena ayuda a encontrar dónde intervenir. **Las emociones intensas no son peligrosas, pero sí agotadoras:** date permiso para descansar después." } ]$steps$::jsonb)
on conflict (slug) do nothing;

-- Recursos de la biblioteca de Materiales (abren el ejercicio correspondiente).
insert into public.materials (title, description, type, category_id, exercise_template_id, duration_minutes, visibility, is_published)
select v.title, v.description, 'exercise', c.id, t.id, t.estimated_minutes, 'assigned', true
from (values
  ('cuadro-panico-entender', 'Entender los ataques de pánico', 'Psicoeducación sobre el pánico: la alarma del cuerpo, el círculo de interpretación catastrófica y evitación, cómo se trabaja en TCC y mitos frecuentes.', 'ansiedad'),
  ('cuadro-panico-practica', 'Mi registro del pánico', 'Registro guiado de una crisis (situación, sensaciones, pensamiento, conducta), reinterpretación de las sensaciones y respiración lenta.', 'ansiedad'),
  ('cuadro-fobias-entender', 'Entender las fobias y la ansiedad social', 'Psicoeducación sobre fobias específicas y ansiedad social: evitación, conductas de seguridad, exposición gradual en TCC y mitos frecuentes.', 'ansiedad'),
  ('cuadro-fobias-practica', 'Mi escalera de exposición', 'Guía para armar una jerarquía de exposición con puntaje de malestar 0 a 100, para revisar y acordar con el psicólogo antes de ponerla en práctica.', 'ansiedad'),
  ('cuadro-toc-entender', 'Entender el TOC', 'Psicoeducación sobre el TOC: obsesiones, compulsiones y neutralización, el círculo que lo mantiene, la EPR en terapia y mitos frecuentes.', 'toc'),
  ('cuadro-toc-practica', 'Mi registro del TOC', 'Registro guiado de disparador, obsesión, malestar y compulsión, y una práctica breve y voluntaria de posponer el ritual. La EPR se planifica en sesión.', 'toc'),
  ('cuadro-trauma-entender', 'Entender el trauma y el estrés postraumático', 'Psicoeducación sobre reacciones al trauma: reexperimentación, evitación, hiperalerta, por qué se mantienen, tratamientos con respaldo y mitos frecuentes.', 'trauma'),
  ('cuadro-trauma-practica', 'Anclarme al presente', 'Ventana de tolerancia, anclaje 5-4-3-2-1 y corporal, y plan de autocuidado con personas seguras. No pide recordar ni escribir sobre el trauma.', 'trauma'),
  ('cuadro-duelo-entender', 'Entender el duelo', 'Psicoeducación sobre el duelo: qué es y qué no es, el modelo de proceso dual, mitos frecuentes, cuándo consultar y qué hacer entre sesiones.', 'duelo'),
  ('cuadro-duelo-practica', 'Duelo: recuerdo y conexión', 'Ejercicio guiado: carta o recuerdo significativo, rituales de conexión con quien ya no está y red de apoyo para los días difíciles.', 'duelo'),
  ('cuadro-burnout-entender', 'Entender el estrés laboral y el burnout', 'Psicoeducación sobre burnout: agotamiento, distanciamiento y menor eficacia, factores del trabajo y personales, mitos y qué hacer entre sesiones.', 'estres'),
  ('cuadro-burnout-practica', 'Burnout: demandas, recursos y límites', 'Ejercicio guiado: inventario de demandas y recursos, límites concretos, micro-pausas y plan de recuperación para el estrés laboral.', 'estres'),
  ('cuadro-sueno-entender', 'Entender el insomnio y el sueño', 'Psicoeducación sobre insomnio: modelo de las 3 P, hiperactivación, condicionamiento cama-vigilia, TCC-I como primera línea, mitos y qué hacer.', 'sueno'),
  ('cuadro-sueno-practica', 'Sueño: diario y hábitos', 'Ejercicio guiado: qué anotar en un diario de sueño de una semana, higiene del sueño y control de estímulos para el insomnio.', 'sueno'),
  ('cuadro-tdah-entender', 'Entender el TDAH en adultos', 'Psicoeducación sobre TDAH adulto: funciones ejecutivas, por qué no es falta de voluntad, estrategias externas, diagnóstico, mitos y qué hacer.', 'tdah'),
  ('cuadro-tdah-practica', 'TDAH: mi sistema externo', 'Ejercicio guiado: sistema externo de lista, agenda y temporizador, dividir tareas, bloques de trabajo tipo pomodoro adaptados y preparar el entorno.', 'tdah'),
  ('cuadro-alimentacion-entender', 'Entender la relación con la comida', 'Qué es y qué no es, el ciclo restricción–atracón–compensación, el valor de comer regularmente, el trabajo en equipo y señales de alarma.', 'alimentacion'),
  ('cuadro-alimentacion-practica', 'Mi registro de comidas y emociones', 'Registro de una comida y su contexto emocional, sin contar calorías, y un borrador de comidas regulares para revisar con el profesional.', 'alimentacion'),
  ('cuadro-autoestima-entender', 'Entender la autoestima', 'Qué es y qué no es la autoestima, la voz crítica, las creencias nucleares, la comparación social y la autocompasión como alternativa.', 'autoestima'),
  ('cuadro-autoestima-practica', 'Logros, cualidades y la voz de un amigo', 'Registro de logros y cualidades, y práctica de autocompasión: responderle a la voz crítica con la voz de un amigo.', 'autoestima'),
  ('cuadro-pareja-entender', 'Entender los problemas de pareja', 'Críticas, defensividad, desprecio y evasión; necesidades y pedidos claros; señales de violencia y por qué priorizar la seguridad.', 'relaciones'),
  ('cuadro-pareja-practica', 'Preparar una conversación difícil', 'Guía para preparar una conversación con «Yo siento… cuando… necesito…», practicar la escucha activa y cuidar la seguridad.', 'relaciones'),
  ('cuadro-regulacion-entender', 'Entender las emociones intensas', 'La función de las emociones, la ventana de tolerancia, la cadena vulnerabilidad–emoción–acción de la DBT y por qué las emociones son olas.', 'regulacion-emocional'),
  ('cuadro-regulacion-practica', 'Habilidades para emociones intensas', 'STOP, TIPP (con precauciones), acción opuesta y registro de la cadena de una emoción intensa, según la DBT.', 'regulacion-emocional')
) as v(slug, title, description, category)
join public.exercise_templates t on t.slug = v.slug
left join public.material_categories c on c.slug = v.category
where not exists (select 1 from public.materials m where m.exercise_template_id = t.id);
